(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-denoising-diffusion-implicit-models-2020"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-1\">一 · 一个晚间高峰的出图队列</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-2\">二 · 马尔可夫反向链为什么把步数焊死</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-3\">三 · 减步数的第一次尝试为何撞墙</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-4\">四 · 非马尔可夫族：把“步数”变成可调参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-5\">五 · 零重训替换与它的部署边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-6\">六 · 从马尔可夫长链到可调度子序列：旧反向链在在线服务里的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-7\">七 · 把“请求”拆成可测的四元组</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-8\">八 · 输入长度分布：提示编码与隐变量分辨率的两种长尾</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-9\">九 · 并发与批大小：CFG 把有效批翻倍后的显存折算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-10\">十 · SLO 与长尾：步数下限是质量约束，不是性能旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-11\">十一 · 负载与方案的双向塑造：调度表是唯一的耦合点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-12\">十二 · 从公式到 kernel：DDIM 单步的算子分解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-13\">十三 · 数据类型：FP16/BF16 是基线，FP8 与 NVFP4 是收益与风险的交换</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-14\">十四 · 累加精度：GEMM 内部与跨步链的两层误差</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-15\">十五 · Blackwell 特性：tcgen05、TMEM、2-SM MMA 如何改变单步成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-16\">十六 · 误差预算的分配：把 S 步的精度责任摊到段上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-17\">十七 · 部署判断：精度档与调度表的联合定档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-18\">十八 · 确定性转移的数值边界：从 FP16 到 NVFP4 的误差放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-19\">十九 · 显存账本的三个账户：权重、激活、轨迹缓冲</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-20\">二十 · 激活峰值才是约束：CFG 双分支与批的折算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-21\">二十一 · 隐变量缓冲的复用与卸载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-22\">二十二 · 带宽瓶颈在哪：权重流、激活流与写回</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-23\">二十三 · 可复算预算的工程用法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-24\">二十四 · 确定性采样的显存边界：没有 KV，账本落在激活与批维上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-25\">二十五 · 从固定长链到可调度步数：批处理的基本单元变了</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-26\">二十六 · Chunked prefill 的类比：把调度表切段以压尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-27\">二十七 · 优先级与抢占：确定性映射让抢占变得廉价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-28\">二十八 · 分离式预填/解码的映射：提示编码与采样步解耦</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-29\">二十九 · 尾延迟怎么压：步对齐、分桶与最小步数下限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-30\">三十 · 调度参数与容量规划的耦合：S 是服务参数不是模型参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-31\">三十一 · 并行切分的四个轴与扩散推理的真实负载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-32\">三十二 · NVLink 5 与 NVSwitch：域内带宽把通信从瓶颈推回计算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-33\">三十三 · All-to-All 与 NIXL：EP 的代价与跨节点传输</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-34\">三十四 · 通信何时成为瓶颈：三个判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-35\">三十五 · 把并行拓扑绑到调度表上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-36\">三十六 · 确定性采样下的并行拓扑边界与通信代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-37\">三十七 · 精度塌陷：低步数下的误差累积与数值放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-38\">三十八 · OOM：批内双分支与激活峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-39\">三十九 · 批抖动与尾延迟：步数不一致的连锁反应</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-40\">四十 · 静默降级：确定性模式下的多样性损失与缓存陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-41\">四十一 · 监控与回滚：把采样参数纳入发布单元</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-42\">四十二 · 确定性采样的失效边界：从数值塌陷到批级尾延迟的定位与回滚</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-43\">四十三 · 论文口径与可核验边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-44\">四十四 · 硬件档位：步数收益在什么机器上才兑现</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-45\">四十五 · batch、并发与有效批的折算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-46\">四十六 · 指标口径：TTFT/TPOT 在扩散负载上的映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-47\">四十七 · 哪些提升不可比：四类常见误读</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-48\">四十八 · 落到工程判断：先建口径表再谈加速</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-49\">四十九 · 确定性采样的口径陷阱：步数收益不等于吞吐收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-50\">五十 · 迁移到非扩散生成器：先看反向链是否真的存在</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-51\">五十一 · 迁到蒸馏与一致性模型：确定性映射是接口，不是终点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-52\">五十二 · 迁到量化与低精度：误差放大的方向不对称</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-53\">五十三 · 迁到服务端批调度：可复现性是缓存的前提，也是并发的约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-54\">五十四 · 不适用与规模上限：三条硬边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-denoising-diffusion-implicit-models-2020-sec-55\">五十五 · 确定性采样的边界：从“能换调度”到“不能省前向”</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:543px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 543.2 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">输入初始隐变量 x_T，按调度表选取长度远小于训练步数的子序列 t_1…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">每步把当前 x_t 与时间步送入噪声预测网络，一次前向得到噪声估计 ε…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">由 ε_θ 与 x_t 解析地估计出干净样本 x0 的预测值，作为该步…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按非马尔可夫转移系数把 x0 预测与 ε_θ 组合，算出 x_{t-1…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">重复至 t=0 输出 x0，再交给后续解码器还原为图像；全过程无随机数…</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-1\">一 · 一个晚间高峰的出图队列</h3>\n<p>设想一个面向 C 端的设计辅助服务：用户在网页上提交提示词，期望在数秒内拿到一张可用的概念图。晚八点流量峰值，队列里同时压着数千个请求，调度器按到达顺序把请求打成批，每批 8 条提示，每条提示做一次无分类器引导（CFG），因此每个采样步实际要跑 16 次网络前向。若后端挂的是当时主流的马尔可夫扩散采样器，预设步数是数百到上千步，那么单条请求的前向次数就是步数的整数倍——几百乘以二。批内所有样本必须共享同一条时间步链，链没走完，这一批的显存就不能释放：当前隐变量 x_t、双分支的中间激活、以及为了下一步继续采样而必须保留的整条噪声轨迹，全都压在显存里。队列的占用时长与步数成正比，吞吐被步数线性拖住，扩容只能靠堆卡，而堆卡又受单批显存上限约束，形成一条越拧越紧的绳。</p>\n<p>这就是 DDIM 出场前推理栈的真实处境。它不是“效果不够好”的问题，而是“结构上不可调度”的问题：采样过程是一条固定长度的马尔可夫链，链长由训练时的扩散步数决定，推理侧没有任何合法手段把它截短。工程上想省时间，只剩两条路——减批大小（牺牲吞吐）或降精度（牺牲质量），两条都不触及根因。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-2\">二 · 马尔可夫反向链为什么把步数焊死</h3>\n<p>旧方案的核心机制是马尔可夫转移：反向过程每一步都从当前 x_t 采样出 x_{t-1}，转移分布里显式含有一个注入的随机噪声项，其方差被训练时的前向过程固定。这意味着 x_{t-1} 的分布依赖 x_t 的完整分布，而不是依赖某个可解析估计的干净样本。于是采样必须逐级走完预设的每一步，不能跳步：跳过任何一级，方差结构就错位，样本立刻退化为噪声或糊块。步数与质量之间是硬耦合，不是软权衡。</p>\n<div class=\"formula\">$$x_{t-1}=\\sqrt{\\alpha_{t-1}}\\,\\hat{x}_0+\\sqrt{1-\\alpha_{t-1}-\\sigma_t^2}\\,\\epsilon_\\theta(x_t,t)+\\sigma_t\\,\\epsilon,\\quad \\hat{x}_0=\\frac{x_t-\\sqrt{1-\\alpha_t}\\,\\epsilon_\\theta(x_t,t)}{\\sqrt{\\alpha_t}}$$</div>\n<p>上式是 DDIM 的转移式，把它与旧方案对照就能看清差别：旧方案的 σ_t 被固定为马尔可夫链对应的值，随机项 σ_t·ε 每步必注入，且转移系数不允许在任意时间子序列上重组。工程后果有三层。其一是延迟：单请求前向次数等于步数乘以 CFG 分支数，步数数百即意味着数百次前向，单条请求的端到端延迟被前向次数直接锁定。其二是显存：批内样本共享时间步，但每条样本要维持自己的 x_t 与激活，CFG 双分支使有效批大小翻倍，显存占用随批线性增长，并发上限被单批激活规模压死。其三是可复现性：每步注入随机噪声，同一隐变量在不同随机种子、不同副本上产出不同结果，重试无法命中同一结果，缓存无法复用，A/B 比对失去基准。这三层叠加，使得服务端既不能靠减步数换吞吐，也不能靠缓存摊薄成本。</p>\n<p>具体到一个 8 条提示、CFG 双分支的批：有效样本数 16，每步 16 次前向，若步数为数百，则单批前向次数在数千量级；批的显存驻留时间等于步数乘以单步前向耗时，队列里每一批都占着这块显存不肯放。运维侧看到的不是“模型慢”，而是“批周转率上不去”，扩容的边际收益被步数稀释。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-3\">三 · 减步数的第一次尝试为何撞墙</h3>\n<p>最直觉的工程动作是把调度表截短：从预设链里均匀抽若干个时间点，只在这些点上做转移。问题在于马尔可夫转移的系数是按相邻步的方差关系推导的，跨步跳跃后，注入噪声的方差与系数不再自洽，单步误差被显著放大，且误差在高噪声段与低噪声段的表现完全不同——高噪声段跳步会让整体结构跑偏，低噪声段跳步则直接抹掉高频细节。结果就是步数一减，样本质量急剧下降，且下降曲线陡峭，没有可用的中间档位。工程上这就等于没有旋钮：要么全步数，要么不可用。</p>\n<p>另一条路是换更快的采样器数值积分，但它同样受制于“每步必须注入随机噪声”的马尔可夫结构，无法把随机性与步数解耦。于是推理栈陷入一个僵局：质量由训练时的链长决定，延迟由链长决定，两者绑死，服务端没有任何参数可以在 SLO 与成本之间做连续调节。这正是论文要动刀的地方——不是优化某一步的算子，而是把反向过程从马尔可夫框架里解放出来。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-4\">四 · 非马尔可夫族：把“步数”变成可调参数</h3>\n<p>论文的机制动作是把反向过程推广到非马尔可夫框架，构造一族与同一训练目标兼容的推理过程，其中每个转移都以 x0 预测为中心：先由网络一次前向得到噪声估计 ε_θ，再解析地反解出干净样本估计 x̂0，然后用系数把 x̂0 与 ε_θ 组合成 x_{t-1}。关键点是这个组合不要求 t 与 t-1 相邻，因此可以在任意单调递减的时间子序列上定义转移，步数 S 由调度表自由选取，而不再被训练链长焊死。方差参数 σ_t 成为唯一的随机性旋钮：取 0 即确定性 DDIM，转移中不含随机项；取马尔可夫链对应值则精确退化为原扩散的随机采样；中间值则在两者之间折中。</p>\n<p>对推理系统的直接代价变化是结构性的。单请求前向次数从“训练链长 × CFG 分支”变为“所选步数 S × CFG 分支”，S 从数百降到数十，前向次数线性下降，端到端延迟随之线性下降——这是材料中唯一可以定性确认的定量关系，不能外推为吞吐提升，因为吞吐还受批调度粒度与显存周转约束。显存侧，由于不再需要维持整条噪声轨迹的随机一致性，批内只需保留当前 x_t 与网络激活，KV 类缓存不适用，但批内样本仍可合并做 CFG 双分支前向，有效批大小为请求数乘以分支数，显存随批线性增长，并发需按显存折算。可复现性侧，σ_t=0 时该步不消耗随机数，同一隐变量与提示在任意副本上输出一致，重试、缓存与结果比对第一次在扩散服务里变得可行，代价是单隐变量只出一个结果，多样性下降，批量服务必须为每请求分配不同隐变量。</p>\n<p>一个具体例子：同一批 8 条提示、CFG 双分支，若 S 取数十而非数百，单批前向次数下降一个数量级，批的显存驻留时间同比例缩短，队列周转率提升；同时因为确定性模式可复现，失败重试可以直接命中缓存而不必重跑整条链。但调度点选取成为新的工程负担：S 越小，单步误差累积越明显，调度点必须同时覆盖高噪声段与低噪声段两端，否则低步数下高频细节崩坏。论文通过比较不同步数与方差设置下的样本质量来刻画这一权衡，未给出具体数值，因此部署侧只能按 SLO 设最小步数下限，而不是一味追低。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-5\">五 · 零重训替换与它的部署边界</h3>\n<p>这套机制在部署上的吸引力在于零重训：训练侧沿用标准扩散的噪声预测网络与加权变分目标，不引入新参数，推理侧只把反向链改写为非马尔可夫转移，已有权重可直接切换采样器。部署改动仅落在调度表与系数实现上，属于推理替换而非模型迭代，灰度与回滚的成本都很低。监控重点因此从“模型精度”转向“单请求前向次数、批内步数一致性、低步数下的质量回归”三项：前两项是容量与调度的直接输入，第三项是 SLO 的守门人。</p>\n<p>边界同样清晰。非马尔可夫框架仍依赖原模型的噪声预测精度，步数压得过低时单步误差被放大，高频细节损失明显；方差参数的选择缺乏理论最优解，需要实验扫描；确定性采样牺牲多样性，同一隐变量只出一个结果。更关键的是，材料未给出数据集规模、FID 数值与硬件档位，服务端的吞吐、显存与量化代价无法从论文核验，只能定性判断步数与前向次数的线性关系。工程判断因此落在一点上：把 S 当作服务参数写入容量模型，用最小步数下限守住质量，用确定性映射换取缓存与重试的确定性收益，而不是把 DDIM 的步数收益直接换算成吞吐承诺。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-6\">六 · 从马尔可夫长链到可调度子序列：旧反向链在在线服务里的边界</h3>\n<p>一个图像生成接口在晚高峰被压到排队：每个请求都要走完预设的数百至上千步反向链，而马尔可夫扩散的每一步都要注入随机噪声，步与步之间不可跳跃、不可合并。服务端的代价是刚性的：单请求前向次数等于预设步数，队列占用时长与步数成正比；显存里要保留当前 x_t 与网络激活，批内样本还必须共享同一条时间轴才能合并前向。更麻烦的是随机性——同一隐变量在不同随机种子下结果不同，重试要重算，缓存无从谈起，跨副本比对结果也无法成立。旧方案的痛点不在单步算子，而在整条链的长度与不可复现性同时锁死了批调度粒度。</p>\n<p>把这条链写成递推看得更清楚：马尔可夫反向每步先采样 ε，再按 <span class=\"formula\">$$x_{t-1}=\\frac{1}{\\sqrt{\\alpha_t}}\\left(x_t-\\frac{1-\\alpha_t}{\\sqrt{1-\\bar\\alpha_t}}\\,\\epsilon_\\theta(x_t,t)\\right)+\\sigma_t\\,\\epsilon$$</span> 组合出下一步。随机项 σ_t ε 使转移成为随机映射，x_T 到 x_0 不是函数关系而是分布关系；步数一减，链的方差结构被破坏，样本质量急剧下降，且下降幅度不可控。工程上这意味着步数是硬下限而非可调参数：想压延迟只能加卡或加副本，单卡吞吐被步数线性拖住，显存中保留的完整噪声轨迹进一步压缩了并发上限。</p>\n<p>失效条件集中在三处。其一，批内一致性：随机采样下同一提示的不同请求必须各自消耗随机数，批合并只省了前向的调度开销，省不掉步数本身。其二，可复现性缺失使重试与缓存失效——一次超时重算就是整条链重跑，尾延迟被放大。其三，CFG 双分支前向让有效批大小翻倍，显存占用随批线性增长，而步数不变时并发只能靠折算显存硬顶。这张表把旧链的代价摊开：</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>马尔可夫反向链</th><th>后果</th></tr></thead><tbody><tr><td>单请求前向次数</td><td>等于预设步数（数百至上千）</td><td>延迟随步数线性上升</td></tr><tr><td>随机性</td><td>每步注入噪声</td><td>结果不可复现，缓存与重试失效</td></tr><tr><td>显存</td><td>保留噪声轨迹与激活</td><td>并发受显存折算限制</td></tr><tr><td>批调度</td><td>批内共享时间轴</td><td>吞吐被步数线性拖累</td></tr></tbody></table>\n<p>这正是非马尔可夫推广要解决的边界：不改网络、不重训，只把反向链改写为以 x0 预测为中心的转移，并让方差参数 σ_t 承担随机性开关——取马尔可夫链对应值即退回原扩散，取 0 则得到确定性映射，使同一隐变量在任意副本上输出一致，重试、缓存与结果比对才成立。代价同时显形：确定性牺牲多样性，每请求须分配不同隐变量；步数压缩放大单步误差，高噪声段与低噪声段的调度点选取直接决定低步数下的细节质量，最小步数下限因此成为 SLO 的一部分而非可无限追低的参数。</p>\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-7\">七 · 把“请求”拆成可测的四元组</h3>\n<p>在 DDIM 的服务语境里，一个请求不是一句提示词，而是一个四元组：<em>(提示编码长度, 初始隐变量 x_T, 采样步数 S, CFG 分支数)</em>。前两项决定单次前向的张量形状与显存驻留，后两项决定前向次数。之所以要拆到这个粒度，是因为 DDIM 的负载结构与传统自回归推理完全不同：没有 KV cache 的增长曲线，没有输出 token 的变长尾部，取而代之的是一条<strong>固定长度 S 的前向链</strong>。这条链的长度由调度表决定，而调度表是部署侧可写的，于是“负载形态”与“方案形态”之间第一次出现了双向可调的关系——服务方可以改 S，S 又反过来定义队列占用时长与批的可行性。</p>\n<p>可核查的测量口径必须落到三个计数器上：单请求前向次数 <code>N_fwd = S × B_cfg</code>（B_cfg 为 CFG 分支数，通常为 1 或 2）；单步激活显存 <code>M_act</code>（由批大小与隐变量分辨率决定，与 S 无关）；以及批内步数一致性标志 <code>flag_uniform_S</code>（批内所有样本是否共享同一时间子序列）。第三个计数器最容易被忽略，却直接决定能否合并前向：DDIM 的每步转移系数依赖 t，若批内样本的调度点不同，就无法用一次 GEMM 覆盖整个批，只能退化为按子批分组或逐样本执行，吞吐立刻塌陷。因此调度表的第一条工程约束是<strong>批内时间步必须对齐</strong>。</p>\n<p>举例：一个 8 样本的批，若全部取 S=20、CFG 双分支，则批级前向次数为 20×2=40 次；若其中 3 个样本因 SLO 分级被要求 S=50，则这 3 个样本无法与前 5 个共享时间步，批被切成 5+3 两组，总前向次数变为 20×2 + 50×2 = 140 次，而有效样本数仍是 8。这就是“负载形态塑造方案”的最直接代价：步数异构比批大小异构更伤吞吐，因为它破坏的是时间维度的合并，而非空间维度的合并。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-8\">八 · 输入长度分布：提示编码与隐变量分辨率的两种长尾</h3>\n<p>DDIM 本身不消费 token 序列，它消费的是文本编码器输出的条件向量与一个固定形状的隐变量。因此“输入长度分布”在这个场景下有两个来源。其一是提示词的 token 数，它只影响文本编码器的一次前向，属于<strong>一次性开销</strong>，不随 S 放大；其二是隐变量分辨率，它决定每步噪声预测网络的计算量与激活显存，属于<strong>被 S 线性放大的开销</strong>。两者的长尾性质截然不同：提示长度长尾影响的是请求进入队列前的预处理延迟，分辨率长尾影响的是每个请求在队列中占用的“前向次数×单步成本”乘积。</p>\n<p>测量口径上，应分别记录 <code>p50/p95/p99</code> 的提示 token 数与隐变量像素数，并把它们与 <code>S</code> 相乘得到单请求的“前向-像素积” <code>W = S × H × W</code>。这个量是容量规划的基本单位，因为单步计算量近似正比于 H×W，而总计算量正比于 S×H×W。用公式表达单请求的计算代价：</p>\n<div class=\"formula\">$$C_{\\text{req}} \\approx S \\cdot B_{\\text{cfg}} \\cdot c_{\\text{step}}(H, W)$$</div>\n<p>其中 <code>c_step</code> 是单次噪声预测前向的计算量，随分辨率近似平方增长。工程判断是：分辨率的长尾必须靠<strong>分级调度</strong>消化，而不是靠单一队列。把高分辨率请求单独成批，可以避免小分辨率样本被大张量拖慢；但代价是高分辨率批的批大小被迫压小，显存利用率下降。反过来，若强行混批，则批的张量形状被最大分辨率撑满，小样本的算力被浪费在填充上。DDIM 的确定性映射在这里提供了一个额外杠杆：同一隐变量与提示的输出可复现，因此高分辨率请求可以在低峰期预计算并缓存结果，把长尾从在线队列挪到离线批次。</p>\n<p>具体例子：若 p99 分辨率的像素数是 p50 的 4 倍，则同一 S 下 p99 请求的单步计算量约为 p50 的 4 倍，其在队列中的占用时长也约为 4 倍。若队列按 FIFO 调度，一个 p99 请求会阻塞其后所有 p50 请求，形成典型的长尾放大。可核查的做法是记录<strong>队列等待时间与执行时间的比值</strong>，当该比值随分位数上升而陡增时，说明长尾已从计算问题转为调度问题。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-9\">九 · 并发与批大小：CFG 把有效批翻倍后的显存折算</h3>\n<p>DDIM 的批处理有一个容易被低估的细节：CFG 在批内表现为双分支前向，即同一批样本要分别以条件向量与空条件向量各跑一次网络。这意味着<strong>有效批大小 = 请求数 × 分支数</strong>，而显存占用与单步激活规模随有效批线性增长。测量口径必须区分“逻辑批”（请求数）与“物理批”（实际进入 GEMM 的样本数），否则并发上限会被高估一倍。可核查的计数器是 <code>B_eff = N_req × B_cfg</code> 与 <code>M_act(B_eff)</code>，并用下式做显存可行性判断：</p>\n<div class=\"formula\">$$M_{\\text{total}} \\approx M_{\\text{weights}} + B_{\\text{eff}} \\cdot m_{\\text{act}}(H, W) + M_{\\text{buf}}$$</div>\n<p>其中 <code>m_act</code> 是单样本单步的激活显存，<code>M_buf</code> 是当前 x_t 与中间量的缓冲。注意 DDIM 不需要保留完整噪声轨迹——这是它相对马尔可夫链式采样的显存优势：每步只需当前 x_t 与网络激活，前一步的中间结果在算出 x_{t-1} 后即可释放。但这一优势只在<strong>步内</strong>成立，跨步并无累积，因此显存曲线是平的而非增长的，这与自回归推理的 KV cache 增长曲线形成鲜明对比。</p>\n<p>并发上限由此可以解析地写出：在给定显存预算下，<code>N_req_max = floor((M_budget - M_weights - M_buf) / (B_cfg · m_act))</code>。这个式子的工程含义是：CFG 开启时并发直接减半，而 DDIM 的步数压缩并不能补偿这一减半——步数只降低时间维度的占用，不降低空间维度的占用。因此“步数少所以并发可以开大”是一个常见误判。可核查的测量应同时报告<strong>批大小、有效批大小、单步激活峰值显存</strong>三项，缺一不可。</p>\n<p>具体例子：若单样本单步激活为 m，权重与缓冲合计为 M0，则在 CFG 双分支下，逻辑并发 N 对应物理批 2N，显存需求为 M0 + 2N·m。若把 N 翻倍而不改 CFG，显存需求增加 2N·m，可能直接越过预算。此时正确做法是降低逻辑并发或关闭 CFG（以质量换吞吐），而不是减少 S——减少 S 只缩短每个请求的驻留时间，不改变瞬时显存峰值。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-10\">十 · SLO 与长尾：步数下限是质量约束，不是性能旋钮</h3>\n<p>DDIM 把采样步数变成可调服务参数，这带来一个诱人的错误推论：既然延迟正比于 S，那把 S 压到极低就能满足任意 SLO。问题在于步数压缩会放大单步误差，高噪声段与低噪声段的调度点选取直接影响低步数下的细节质量。因此 S 的下限是一个<strong>质量约束</strong>，由 SLO 中的质量条款（而非延迟条款）决定。可核查的测量口径是把 SLO 拆成两条独立曲线：延迟分位数曲线（随 S 线性）与质量回归曲线（随 S 非线性恶化），两条曲线的交点才是可部署的 S 区间。</p>\n<p>长尾在这个框架下有新的形态。传统推理的长尾来自输出长度，DDIM 的长尾来自<strong>重试与缓存未命中</strong>。确定性模式取 σ_t=0，转移中不含随机噪声项，同一隐变量与提示在任意副本上输出一致，因此失败重试可以复用已算出的中间 x_t，而不必从头再跑 S 步。这把重试的代价从 O(S) 降到 O(S_remaining)。但代价是多样性下降：单一隐变量只能产出一个结果，批量服务必须为每请求分配不同隐变量，否则批内样本会退化为同一张图。可核查的计数器是<strong>隐变量去重率</strong>与<strong>缓存命中率</strong>，前者过低说明多样性受损，后者过低说明确定性带来的复用收益没被吃到。</p>\n<p>举例：若某请求在第 k 步失败，确定性模式下可从 x_{t_k} 继续，剩余步数 S−k；随机模式下则因每步注入噪声而无法精确复现中间态，只能整链重跑。这就是“方案反过来限制负载”的一面：一旦部署选择确定性采样，重试策略与缓存键的设计就被固定为以隐变量为主键，负载的重试放大系数也随之确定。工程判断是：把 S 的下限写进调度表而非请求参数，防止上游为追延迟而突破质量底线。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-11\">十一 · 负载与方案的双向塑造：调度表是唯一的耦合点</h3>\n<p>把上述几条收拢，可以看到 DDIM 部署中负载与方案只有一个耦合点：<strong>调度表</strong>。调度表定义了时间子序列 t_1>…>t_S，它同时是质量参数（决定低步数下的细节保真）与负载参数（决定单请求前向次数）。负载侧的形状——批大小、CFG 分支、分辨率分布、SLO 分级——通过调度表映射为前向次数与显存峰值；方案侧的选择——确定性或随机、步数下限、批内对齐策略——又反过来约束了负载能长成什么样。可核查的测量应把调度表本身作为配置项记录，包括 S、σ_t 取值、批内对齐标志，并与吞吐、延迟分位数、质量回归指标联合上报。</p>\n<p>一个具体的机制例子：批内对齐要求所有样本共享同一时间子序列，这直接禁止了“按请求动态选 S”的做法。若产品要求对不同用户给不同 S，则调度器必须先按 S 分组，再在组内成批，组间串行或并行占用不同 SM。这使有效批大小随 S 的分布碎片化，吞吐对 S 分布的敏感度远高于对平均 S 的敏感度。因此容量规划不能只用平均 S，必须用 S 的分布做卷积。用伪代码表达分组逻辑：</p>\n<ul>\n<li>按 (S, 分辨率档, CFG 开关) 三元组对到达请求做哈希分组；</li>\n<li>每组内按到达时间成批，批大小受 <code>M_act(B_eff)</code> 约束；</li>\n<li>组内共享调度表，一次前向覆盖整批；组间独立排队；</li>\n<li>记录每组的批大小、等待时间、前向次数，作为容量回归的输入。</li>\n</ul>\n<p>代价在于：分组越细，批越小，单批的算力利用率越低；分组越粗，批内对齐越难维持，可能出现部分样本被迫使用非最优 S。这是负载形态与方案形态互相拉扯的典型位置，也是 DDIM 服务化时最需要实测而非推算的地方。论文未给出硬件档位与吞吐数据，因此不能把步数收益直接换算为吞吐提升；可核查的做法是在目标硬件上扫描 S 与批大小的二维网格，记录前向次数、显存峰值与延迟分位数，用实测曲线替代线性外推。</p>\n<p>最后落在一条工程判断上：DDIM 的负载治理不应围绕“平均步数”做文章，而应围绕<strong>步数分布的方差</strong>。方差越小，批内对齐越容易，有效批越大，前向次数的合并率越高；方差越大，调度器被迫碎片化分组，步数压缩带来的线性收益被分组开销吃掉。把 S 的方差作为一级监控指标，比监控平均延迟更能提前发现吞吐劣化。</p>\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-12\">十二 · 从公式到 kernel：DDIM 单步的算子分解</h3>\n<p>把 DDIM 的转移式拆成算子，才能谈精度。给定当前隐变量 <code>x_t</code> 与时间步 <code>t</code>，网络一次前向输出噪声估计 <code>ε_θ(x_t,t)</code>；随后两步是纯逐元素代数：先算 <code>x̂_0=(x_t−√(1−α_t)·ε_θ)/√α_t</code>，再算 <code>x_{t−1}=√α_{t−1}·x̂_0+√(1−α_{t−1}−σ_t²)·ε_θ+σ_t·ε</code>。落到 Blackwell 上，这三段对应三类 kernel：噪声预测网络（主体是卷积或 DiT 的 GEMM 与 attention）、逐元素仿射组合（elementwise）、以及确定性模式下被整段消除的随机项。确定性 DDIM 取 <code>σ_t=0</code>，第三段直接消失，只剩两次标量乘加与一次加法，可融合为单个 elementwise kernel，读写各一遍 <code>x_t</code> 与 <code>ε_θ</code>。融合的意义在带宽：若把 x̂_0 与 x_{t−1} 分两个 kernel 落盘，中间张量要多一次写和一次读，在 HBM 带宽受限的逐元素段上，这几乎是两倍代价。工程上应把系数 <code>√α_{t−1}</code>、<code>√(1−α_{t−1})</code>、<code>1/√α_t</code>、<code>√(1−α_t)</code> 在调度表构建时预计算成标量数组，kernel 只做乘加，避免每步在 device 上重算平方根。</p>\n<p>一个具体例子：批大小 B、隐变量通道 C、分辨率 H×W 的潜空间张量，单步 elementwise 段需读 <code>x_t</code> 与 <code>ε_θ</code> 共 2·B·C·H·W 个元素、写 <code>x_{t−1}</code> 一份。以 BF16 计，每元素 2 字节，若 B·C·H·W 达到千万量级，单步这一段的流量就是数十 MB 级，在数 TB/s 级 HBM 上耗时在微秒量级——相比网络前向的毫秒级可以忽略，但前提是融合。若拆成三个 kernel，这段就从微秒级涨到数倍，在低步数（S 很小）场景下会侵蚀步数压缩带来的收益，因为固定开销占比上升。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-13\">十三 · 数据类型：FP16/BF16 是基线，FP8 与 NVFP4 是收益与风险的交换</h3>\n<p>DDIM 的数值敏感点不在逐元素段，而在噪声预测网络。该段是 GEMM 与 attention 的主体，也是唯一值得降精度的地方。BF16 与 FP16 在 Blackwell 上都是成熟基线：BF16 动态范围大，适合激活中可能出现的大幅值；FP16 尾数多一位，适合权重与需要更细粒度的累加输入。选择取决于网络中哪一侧更容易溢出——扩散模型的激活在高噪声段（t 接近 T）幅值显著大于低噪声段，这是时间步条件带来的分布漂移，因此按时间步分段选精度是有依据的：高噪声段用 BF16 保范围，低噪声段可用 FP16 换尾数。</p>\n<p>FP8（E4M3 存权重与激活、E5M2 备选）与 NVFP4（E2M1 加块级缩放）把位宽进一步压低，代价是量化误差进入 <code>ε_θ</code>。这个误差不会停在当步：<code>x̂_0</code> 由 <code>ε_θ</code> 解析算出，误差按 <code>1/√α_t</code> 放大后进入 <code>x_{t−1}</code>，再作为下一步输入。也就是说 DDIM 的确定性反而让误差沿步链单向累积、没有随机噪声去“洗掉”它——这是与马尔可夫采样在数值上的关键差别，后者每步注入的随机项会部分掩盖量化误差。步数越少，单步承担的精度责任越大，因此低步数 + 低精度的组合必须联合评估，不能分别定档。</p>\n<div class=\"formula\">$$\\hat{x}_0=\\frac{x_t-\\sqrt{1-\\alpha_t}\\,\\epsilon_\\theta}{\\sqrt{\\alpha_t}},\\qquad \\delta\\hat{x}_0\\approx\\frac{\\sqrt{1-\\alpha_t}}{\\sqrt{\\alpha_t}}\\,\\delta\\epsilon_\\theta$$</div>\n<p>公式逐项：<code>δ ε_θ</code> 是量化引入的噪声估计误差；系数 <code>√(1−α_t)/√α_t</code> 即信噪比的倒数平方根，在 t 大（α_t 小）时极大，在 t 小（α_t 接近 1）时趋近 0。结论直接：高噪声段的量化误差被放大得最厉害，低噪声段几乎不放大。所以 FP8/NVFP4 的激进档位应优先用在调度表尾段（低噪声、细节精修步），头段保留 BF16；这与“全网络统一低精度”的朴素做法相反，是按时间步分档的精度调度。</p>\n<p>系统代价：FP8 相对 BF16 把 GEMM 的权重与激活流量减半，Tensor Core 吞吐翻倍，直接缩短单步前向时间；NVFP4 再减半，但需要块级缩放因子（每 16 或 32 元素一个 scale）随权重常驻，显存里多出一份小张量，且反量化在 kernel 内做，增加指令开销。对 DDIM 而言，收益是单请求前向次数 S 乘以单步时间，两者都降才是真收益；若量化只降单步时间而迫使 S 上调以补偿质量，净收益可能归零。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-14\">十四 · 累加精度：GEMM 内部与跨步链的两层误差</h3>\n<p>低精度输入不等于低精度累加。Blackwell 的 Tensor Core 在 FP8 与 NVFP4 路径上以更高位宽累加（FP8 路径通常 FP32 累加，NVFP4 路径同样在块内做高精度累加再缩放），因此单次 GEMM 的舍入误差主要来自输入量化而非累加。真正的风险在跨步链：<code>x_{t−1}</code> 被写回显存时若以 BF16 存储，每步引入一次舍入，S 步累积 S 次。确定性 DDIM 没有随机项扰动，这些舍入误差单调叠加，表现为低步数下细节偏移、高步数下反而因每步修正而收敛。工程判断：隐变量主存用 BF16 可接受，但在调度表头段（高噪声、误差放大系数大）可临时升到 FP32 暂存，只在进入低噪声段后回落——代价是显存占用翻倍于该段，需在批调度时按段折算并发。</p>\n<p>伪代码思路：调度表按段标注精度档，<code>for t in schedule: eps = net(x, t, dtype=seg[t].net_dtype); x = combine(x, eps, coef[t], acc_dtype=seg[t].acc_dtype)</code>。这里 <code>combine</code> 的累加类型与输出存储类型分离，是控制跨步误差的关键开关。代价是 kernel 模板按 dtype 组合实例化，编译产物变多，但运行时无分支。</p>\n<p>一个具体例子：CFG 双分支前向在批内表现为有效批大小 = 请求数 × 2。若两分支用不同精度档（条件分支 BF16、无条件分支 FP8），则批内张量 dtype 不一致，无法合并成单个 GEMM，只能拆两次前向，吞吐受损。因此 CFG 场景下精度档必须按分支对齐，宁可整体降一档也不要拆批——这是精度策略与批调度耦合的典型代价。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-15\">十五 · Blackwell 特性：tcgen05、TMEM、2-SM MMA 如何改变单步成本</h3>\n<p>第五代 Tensor Core 的 tcgen05 指令族把矩阵乘的累加器放在 TMEM（Tensor Memory）而非寄存器堆。对 DDIM 的意义在于：噪声预测网络的 GEMM 输出不再经寄存器中转，累加结果直接在 TMEM 中完成，减少了寄存器压力与搬运指令。TMEM 容量有限，因此 tile 划分要按 TMEM 容量反推，而不是按寄存器数反推；这改变了 kernel 的 tiling 启发式。2-SM MMA（两 SM 协同执行一次 MMA）把单个 MMA 的 M 维拉长，适合大 batch 的 GEMM——DDIM 批内样本共享同一时间步，天然是大 M 场景，2-SM 模式能把批维铺满，提高 Tensor Core 占用率。</p>\n<p>系统代价：tcgen05 路径的启动与同步开销高于传统 MMA，小 batch 或低分辨率潜空间下可能不划算；2-SM MMA 要求两个 SM 的 tile 严格配对，调度不齐时一个 SM 空转，等效吞吐下降。因此 DDIM 服务端的并发下限应由 tile 形状决定：批太小则 2-SM 配不齐，退回单 SM 路径，单步时间上升，步数压缩的收益被抵消。这是“步数少、批要够大”的工程约束来源。</p>\n<p>另一个特性是异步拷贝与 TMA 在逐元素段的可用性：融合后的 combine kernel 可用 TMA 做批量搬运，把 <code>x_t</code> 与 <code>ε_θ</code> 的读合并为流水，掩盖延迟。代价是 TMA 描述符需按张量形状预建，调度表切换分辨率时要重建，属于部署期一次性开销。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-16\">十六 · 误差预算的分配：把 S 步的精度责任摊到段上</h3>\n<p>DDIM 的确定性使误差预算可解析分配。设第 i 步引入的相对误差为 <code>e_i</code>，经后续步的系数链传播到终点的放大因子为 <code>Π_{j>i} √α_{t_j−1}/√α_{t_j}</code> 一类乘积（由转移式逐级代入得到），则总误差是各步误差按放大因子加权和。高噪声段步的放大因子大，低噪声段步的放大因子趋近 1。由此得到工程规则：精度预算应向调度表头段倾斜，头段用高精度、尾段用低精度，且头段的步数选取要更密（调度点覆盖高噪声段两端），因为头段单步误差既大又被放大最狠。</p>\n<p>代价核算：头段升精度意味着该段 GEMM 用 BF16 而非 FP8，单步时间上升；但头段步数在总 S 中占比小（调度表通常在高噪声段取较少点、低噪声段取较多点以保细节），因此总延迟增幅有限。反之若为省显存把头段也压到 NVFP4，则需上调 S 补偿，前向次数线性增加，延迟反而更差。这是“精度换步数”与“步数换精度”之间的双向权衡，DDIM 的解析结构让这个权衡可以被计算而非试错。</p>\n<p>一个具体例子：同一隐变量在确定性模式下可复现，因此可用两次不同精度档的运行做差分，把差异图作为误差分布的可视化诊断——高噪声段差异集中在低频结构，低噪声段差异集中在高频纹理。这直接指导分段精度档的切分点，而不必依赖 FID 这类聚合指标（材料未给出数值，只能定性）。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-17\">十七 · 部署判断：精度档与调度表的联合定档</h3>\n<p>把上述收敛成一条工程判断：DDIM 的精度策略不是“选一个 dtype”，而是“按调度表分段选 dtype 组合”，且该组合必须与批大小、CFG 分支数、TMEM tile 形状联合定档。约束链是：批太小 → 2-SM MMA 配不齐 → 单步时间上升 → 需要更大批 → 显存受限 → 需要更低精度存激活 → 低精度误差在高噪声段被放大 → 需要头段升精度 → 头段显存回升。这条链没有单点最优，只有按 SLO 的最小步数下限与显存上限之间求可行解。确定性采样还带来一个部署侧的硬约束：同一隐变量只出一个结果，批量服务必须为每请求分配不同隐变量，缓存命中只能发生在“同隐变量 + 同提示 + 同调度表 + 同精度档”四元组完全一致时——精度档一变，缓存即失效，这是把精度当服务参数的直接代价。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-18\">十八 · 确定性转移的数值边界：从 FP16 到 NVFP4 的误差放大</h3>\n<p>DDIM 的转移式把每步输出写成三项加权和：<div class=\"formula\">$$x_{t-1}=\\sqrt{\\alpha_{t-1}}\\,\\hat{x}_0+\\sqrt{1-\\alpha_{t-1}-\\sigma_t^2}\\,\\epsilon_\\theta+\\sigma_t\\epsilon,\\quad \\hat{x}_0=\\frac{x_t-\\sqrt{1-\\alpha_t}\\,\\epsilon_\\theta}{\\sqrt{\\alpha_t}}$$</div>取 σ_t=0 后，第三项消失，剩下两项系数平方和为 1，形式上是一次保范的插值。真正决定精度的是 x̂₀ 的除法：α_t 在低噪声段接近 1，在高噪声段接近 0，分母越小，ε_θ 的量化误差被放大得越厉害。把 ε_θ 的绝对误差记为 δ，则 x̂₀ 的误差约为 δ/√α_t，再乘 √α_{t-1} 传到下一步。这意味着同一份 FP8 或 NVFP4 权重，在高噪声段（α_t 小）的敏感度远高于低噪声段，误差沿 S 步链式累积而非均匀分布。工程上不能对所有时间步用同一精度档位，而应按 α_t 分档：高噪声段保留 BF16 累加甚至 FP16 权重，低噪声段才放开到 FP8/NVFP4。</p>\n<p>Blackwell 的 tcgen05 与 TMEM 改变了这条链的代价结构。第五代 Tensor Core 的 MMA 累加器驻留在 TMEM 而非寄存器堆，单次 2-SM MMA 可让两个 SM 协同完成更大 K 维的乘加，减少中间结果回写。对 DDIM 而言，每步只有一次噪声预测前向，GEMM 规模由批大小与 CFG 分支数决定，属于典型的低算术强度、访存受限形态：权重读取带宽往往比算力更早成为瓶颈。NVFP4 把权重压到 4 bit，理论上把权重带宽需求降到 FP16 的四分之一，但块缩放（block scaling）引入的量化步长会直接进入 δ。若批内样本共享同一时间步，2-SM MMA 的收益体现在单次前向的 K 维拼接上；若批被 CFG 拆成双分支，有效批翻倍，TMEM 占用与单步激活同步上升，需按显存折算并发，而非按请求数。</p>\n<p>失效条件集中在两处。其一是步数压到极低时，调度点稀疏，高噪声段与低噪声段之间缺少过渡，x̂₀ 的单步误差没有后续步骤修正，高频细节直接崩坏；此时再降精度等于在已被放大的误差上再叠一层量化噪声，质量回归不可逆。其二是确定性模式下 σ_t=0 使转移完全由网络输出决定，任何数值抖动都会稳定复现为同一偏差，缓存与重试虽然一致，但错误也被固化，无法靠随机种子“碰”出好结果。可用的折中是让 σ_t 取小正值，用少量随机项打散量化误差的相干累积，代价是牺牲部分可复现性。</p>\n<table class=\"mini\"><thead><tr><th>精度档位</th><th>权重带宽</th><th>x̂₀ 误差来源</th><th>适用时间步</th></tr></thead><tbody><tr><td>BF16</td><td>基准</td><td>舍入噪声，δ 最小</td><td>高噪声段、低步数</td></tr><tr><td>FP8</td><td>约减半</td><td>块缩放步长进入 δ</td><td>中低噪声段</td></tr><tr><td>NVFP4</td><td>约四分之一</td><td>缩放步长显著放大 δ/√α_t</td><td>仅低噪声段、步数充足时</td></tr></tbody></table>\n<p>系统代价的落点是显存与带宽而非纯算力：单请求前向次数等于 S，延迟随 S 线性下降，但每一步的权重流经量由精度档位决定，NVFP4 省下的是带宽与显存驻留，不是 Tensor Core 周期。真正的工程判断是——把精度分档绑定到调度表的时间子序列上，让高噪声段的少数几步走 BF16、低噪声段走 NVFP4，用步数换精度余量，而不是全局一刀切。</p>\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-19\">十九 · 显存账本的三个账户：权重、激活、轨迹缓冲</h3>\n<p>在 Blackwell 上给 DDIM 做容量规划，第一件事是把显存拆成三个互不挪用的账户。权重账户是静态的：噪声预测网络的全部参数，按部署精度折算，NVFP4 权重每参数 0.5 字节、FP8 每参数 1 字节、BF16 每参数 2 字节，加上 scale 与元数据的少量开销。激活账户是动态的：单步前向的中间张量，随批大小与分辨率线性增长，是峰值显存的主要来源。第三个账户常被忽略——DDIM 虽然不需要 KV cache，但确定性采样要求保留当前 x_t 与 x0 预测，且批内样本共享时间步调度，需要一块与批大小成正比的隐变量缓冲。</p>\n<p>关键在于，DDIM 的显存结构与自回归解码有本质差异。自回归的 KV cache 随序列长度单调增长，是长尾请求的显存杀手；DDIM 的隐变量缓冲尺寸固定为 batch × C × H × W × dtype，与步数 S 无关——步数只影响时间，不影响空间。这意味着 DDIM 的显存预算是可静态复算的，不需要为长请求预留增长空间。反过来说，步数压缩带来的收益全部落在延迟与算力侧，显存侧几乎不动，这一点在容量规划中必须讲清楚，否则容易把步数收益错误折算成显存节省。</p>\n<div class=\"formula\">$$M_{\\text{total}} = \\underbrace{P \\cdot b_w}_{\\text{权重}} + \\underbrace{B_{\\text{eff}} \\cdot A_{\\text{step}}(H,W)}_{\\text{激活峰值}} + \\underbrace{B \\cdot C \\cdot H \\cdot W \\cdot b_x \\cdot k}_{\\text{隐变量缓冲}}$$</div>\n<p>其中 P 为参数量，b_w 为每参数字节，B_eff 为有效批大小（请求数 × CFG 分支数），A_step 为单样本单步激活字节数，b_x 为隐变量精度字节，k 为需要同时驻留的隐变量份数（当前 x_t 与 x0 预测至少两份）。举例：一个 2B 参数的噪声预测网络以 FP8 部署，权重约 2 GB；在 1024×1024 潜空间、批 8、CFG 双分支即 B_eff=16 的情形下，激活峰值往往数倍于权重，成为真正的约束项。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-20\">二十 · 激活峰值才是约束：CFG 双分支与批的折算</h3>\n<p>DDIM 每步只做一次噪声预测前向，单请求前向次数等于 S，这是延迟侧的线性关系。但显存侧的关系不是线性的 S，而是线性的 B_eff。CFG 在批内表现为双分支前向：条件分支与无条件分支共享同一时间步，可以合并成一个 2B 的批做一次前向，也可以拆成两次。合并做的好处是 kernel 启动次数减半、SM 占用更饱满；代价是激活峰值翻倍，因为两条分支的中间张量必须同时驻留到合并输出。</p>\n<p>工程判断在这里很具体：如果激活账户已经逼近上限，拆分支串行执行能把峰值压回单分支水平，代价是前向次数翻倍、延迟上升；如果显存有余而延迟敏感，合并执行更优。Blackwell 的 tcgen05 与 TMEM 让大 batch 的 MMA 效率更高，但 TMEM 本身是有限资源，2-SM MMA 模式下两个 SM 共享一块 TMEM，批过大时 TMEM 容量而非 HBM 容量先成为瓶颈。因此“按显存折算并发”这句话要拆成两层：先看 HBM 能否放下 B_eff 的激活峰值，再看 TMEM 能否放下单次 MMA 的操作数块。</p>\n<ul>\n<li>机制：CFG 双分支合并为 2B 批，一次前向出两个噪声预测，再解析组合。</li>\n<li>代价：激活峰值随 B_eff 线性上升，TMEM 占用随单次 MMA 的 tile 尺寸上升。</li>\n<li>例子：批 8、双分支合并即 B_eff=16；若激活账户只剩单分支余量，则必须拆成两轮各批 8。</li>\n</ul>\n<p>调度侧还有一个隐含约束：批内样本共享同一时间步子序列，因此批内所有请求必须用相同的 S 与相同的调度点。混合步数的请求不能塞进同一批，否则短步数请求要等长步数请求走完，队列占用被拉长。这直接限制了连续批处理的灵活性——DDIM 的批调度粒度是“同 S 同调度表”，而不是逐 token 的细粒度插入。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-21\">二十一 · 隐变量缓冲的复用与卸载</h3>\n<p>DDIM 的确定性映射带来一个自回归解码没有的复用机会：同一隐变量与提示在任意副本上输出一致，因此结果可以缓存、重试可以命中、批内不同请求若共享隐变量则中间结果可复用。但更实际的复用发生在步与步之间——x0 预测在每步都要算，若调度表在高噪声段连续两步的系数变化很小，理论上可跳过重算，但论文的框架并不提供误差界，跳过会直接放大单步误差，属于需要实测的取舍，不能当作免费优化。</p>\n<p>卸载策略上，DDIM 比自回归简单得多：没有随序列增长的 KV，卸载对象只有权重分片与隐变量缓冲。权重可按层切分，在层间流水时把非当前层权重放到主机内存，用 NVLink 5 或 PCIe 回填；隐变量缓冲则必须常驻，因为每步都要读写。Blackwell 的 HBM3e 容量给出了硬上限：单卡容量决定单副本能承载的最大 B_eff，多卡张量并行则把权重与激活按卡切分，但隐变量缓冲在张量并行下通常需要复制或按空间切分，切分方式影响每卡的缓冲份额。</p>\n<div class=\"formula\">$$B_{\\max} = \\left\\lfloor \\frac{M_{\\text{HBM}} - M_{\\text{weight}} - M_{\\text{reserve}}}{A_{\\text{step}} \\cdot k_{\\text{cfg}} + C \\cdot H \\cdot W \\cdot b_x \\cdot k} \\right\\rfloor$$</div>\n<p>这个式子是可复算预算的核心：给定卡型容量、部署精度、分辨率与 CFG 开关，直接算出单副本最大批。举例：若单卡 HBM3e 容量为 192 GB 量级，权重 FP8 占 2 GB，预留 10% 给碎片与通信缓冲，剩余容量除以单样本激活加缓冲的字节数，得到 B_max；再把 B_max 除以 CFG 分支数得到请求并发上限。分辨率翻倍会让 H×W 变为四倍，激活与缓冲同步膨胀，B_max 近似按四分之一收缩——这是分辨率与并发之间最直接的兑换率。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-22\">二十二 · 带宽瓶颈在哪：权重流、激活流与写回</h3>\n<p>DDIM 单步的计算强度取决于批大小。批小时，每步前向要把权重从 HBM 读一遍，权重流量与批大小无关，算术强度低，瓶颈在 HBM 带宽；批大时，权重读取被摊薄，瓶颈转向激活的读写与 MMA 吞吐。Blackwell 的 HBM3e 带宽是固定预算，权重流占多少、激活流占多少，决定了单步时间下界。</p>\n<p>确定性采样对数值误差敏感，低精度部署时权重流的字节数下降会直接改善带宽瓶颈，但量化误差会在低步数下被放大——这与精度部分的结论衔接，此处只强调带宽账：FP8 权重把权重流减半，NVFP4 再减半，在批小、带宽受限的场景收益最明显；批大、算力受限时，量化收益主要落在 MMA 吞吐而非带宽。写回侧，隐变量缓冲每步读写一次，分辨率越高写回流量越大，且这部分流量无法通过量化权重消除，只能靠降低隐变量精度或减少同时驻留份数来压。</p>\n<table class=\"mini\"><thead><tr><th>账户</th><th>随什么增长</th><th>瓶颈形态</th><th>压缩手段</th></tr></thead><tbody><tr><td>权重</td><td>参数量 × 精度</td><td>小批时 HBM 带宽</td><td>FP8/NVFP4、层间卸载</td></tr><tr><td>激活</td><td>B_eff × 分辨率</td><td>大批时 TMEM 与算力</td><td>拆 CFG 分支、降分辨率</td></tr><tr><td>隐变量缓冲</td><td>B × 分辨率 × 精度</td><td>写回带宽</td><td>降精度、减少驻留份数</td></tr></tbody></table>\n<p>一个具体例子：批 1 的交互式出图，权重流主导单步时间，量化权重直接缩短每步；批 32 的离线批处理，激活与 MMA 主导，量化权重收益被摊薄，此时应优先保证 TMEM 的 tile 效率与批内调度一致性。同一套硬件，两种负载形态的优化重点完全不同，容量规划必须按负载形态分别做。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-23\">二十三 · 可复算预算的工程用法</h3>\n<p>把上面的账本落成一张可复算的表，服务端在扩容与调参时按三步走。第一步定分辨率与 CFG 开关，算出单样本激活与缓冲字节；第二步按部署精度算权重字节并加预留；第三步用容量除以前两者之和得到 B_max，再除以分支数得到并发上限，最后用 S 乘以单步时间估算队列占用时长，与 SLO 的延迟目标对齐。</p>\n<ul>\n<li>机制：预算表以 B_max 为输出，以分辨率、精度、CFG 为输入，任何一项变动都触发重算。</li>\n<li>代价：分辨率翻倍使 B_max 近似四分之一，是并发与画质之间最硬的兑换。</li>\n<li>例子：同一卡型下，1024² 与 512² 的 B_max 差约四倍，若 SLO 要求固定并发，则分辨率必须让位。</li>\n</ul>\n<p>需要强调的是，DDIM 的步数收益不能直接换算成吞吐提升。步数从数百降到数十，单请求前向次数线性下降，延迟线性改善；但吞吐取决于批调度与显存能容纳的并发，步数减少只缩短了每个批占用 SM 的时长，让单位时间内能跑更多批，真正的吞吐上限仍由 B_max 与单步时间共同决定。论文未给出硬件档位与吞吐数据，因此预算表只能给出容量侧的上界，吞吐侧必须实测填充。</p>\n<p>最后一个工程判断落在调度表与显存的耦合上：调度点选取影响低步数下的细节质量，而步数下限由 SLO 决定，不是越低越好。把 S 压到显存允许的最小值并不划算——显存不随 S 变化，压 S 只省时间不省显存，却放大单步误差。正确的做法是先用预算表定 B_max 与分辨率，再在时间预算内选满足质量下限的最大 S，让显存账户与延迟账户各自独立收敛。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-24\">二十四 · 确定性采样的显存边界：没有 KV，账本落在激活与批维上</h3>\n<p>DDIM 的显存账本与自回归解码器结构不同：它不存在随序列增长的 KV cache，因为每步只做一次噪声预测前向，当前 x_t 与网络激活即为全部中间态。真正决定占用的是批维与 CFG 分支：有效批大小 = 请求数 × 分支数，单步激活随有效批线性增长，权重则是固定项。设权重显存 W、单样本单步激活 a、有效批 B_eff、精度字节 p，则峰值约为 <span class=\"formula\">$$M_{\\text{peak}} \\approx W + B_{\\text{eff}}\\cdot a \\cdot p + M_{\\text{out}}$$</span> 其中 M_out 为输出 x0 与解码缓冲。这条式子说明：步数 S 不进显存公式，只进时间；压步数省的是延迟与队列占用，不省显存。因此把 DDIM 的步数收益直接换算成显存节省是错的，工程上应把并发按上式反解，而不是按步数折算。</p>\n<p>失效条件集中在三处。其一，确定性模式下 σ_t=0，同一隐变量只产出一个结果，批量服务必须为每请求分配不同隐变量，否则批内样本重复、吞吐虚高而有效产出为零；缓存复用只对“同隐变量同提示”的重试与比对成立，不能当作跨请求去重。其二，步数压到极低时单步误差被放大，高噪声段与低噪声段的调度点选取直接决定细节是否崩坏，需按 SLO 设最小步数下限而非一味追低。其三，材料未给出量化方案与硬件档位，低精度下确定性采样对数值误差更敏感，需以步数补偿换取质量，这一步的代价是前向次数回升，与延迟目标直接冲突。</p>\n<p>系统代价的落点是带宽与调度粒度。每步一次前向意味着权重被反复读取，单请求的权重流量约与 S 成正比，权重带宽占用随并发线性叠加；当批被 CFG 双分支撑大时，激活写回与读出的带宽压力上升，而计算密度并未同比提高。调度侧则受“批内步数一致”约束：批内样本必须共享同一时间子序列，否则无法合并前向，长短请求混批会拉长整批的队列占用时长。可复算的例子：若单样本单步激活为 a、有效批为 2N（N 个请求各双分支），则激活项为 2N·a·p，权重项 W 固定；把 N 翻倍，激活翻倍而权重不变，此时显存瓶颈从权重转向激活，扩容手段应是降精度或拆批，而非加卡。</p>\n<table class=\"mini\"><thead><tr><th>项</th><th>随步数 S</th><th>随有效批 B_eff</th><th>工程手段</th></tr></thead><tbody><tr><td>权重 W</td><td>不变</td><td>不变</td><td>量化、分副本共享</td></tr><tr><td>激活</td><td>不变（单步驻留）</td><td>线性</td><td>拆批、降精度</td></tr><tr><td>带宽流量</td><td>线性</td><td>线性</td><td>提高计算密度、合并前向</td></tr></tbody></table>\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-25\">二十五 · 从固定长链到可调度步数：批处理的基本单元变了</h3>\n<p>马尔可夫扩散的服务形态是“一条链跑到底”：一个请求从 t=T 走到 t=0，中间任何一步都不能跳过，批内所有样本必须共享同一条时间轴。DDIM 把反向过程改写为以 x0 预测为中心的非马尔可夫转移后，单请求的工作量从“固定数百至上千次前向”变成“S 次前向”，S 由调度表决定。这不是简单的常数缩小，而是把<strong>批处理的原子单位从“链”改成了“步”</strong>：调度器可以在任意两个调度点之间插入新请求，因为每个请求只依赖自己的 x_t 与当前时间步，不依赖前序随机数。连续批处理（continuous batching）在自回归解码里靠“每步只推进一个 token”实现请求进出，DDIM 提供了同构的条件——每步只推进一个调度点，批内成员可以在步边界上增删。代价在于批内样本必须共享同一时间步才能合并前向，因此调度器要维护“步同步”约束：新请求要么等到下一个调度点对齐，要么单独起一个小批。前者增加排队时延，后者牺牲合并效率。</p>\n<p>设批内有 n 个请求、每请求 CFG 双分支，则单步有效前向样本数为 2n，单步激活显存随 n 线性增长。若显存上限为 M、单样本单步激活为 a，则并发上限 n_max ≈ M/(2a)（忽略权重与 x_t 本身）。这个式子说明：<strong>DDIM 的并发不是由 KV cache 决定的</strong>——扩散没有自回归的 KV 增长，显存占用在整条采样过程中基本恒定，瓶颈是单步激活的峰值。这与 LLM 服务里“显存随上下文长度增长”的形态完全不同，容量规划要按峰值激活而非按序列长度折算。</p>\n<p>具体例子：一个 1024×1024 出图服务，S=20，CFG 双分支。若单样本单步激活为 a，则 n=8 时单步前向 16 个样本，n=32 时 64 个。调度器若按 32 并发配置，单步时延由 64 个样本的 GEMM 决定；若请求到达率不足，批内会出现“半空批”，此时把两个不同调度点的请求强行合并会破坏步同步，只能降批或等待。工程判断是：<strong>DDIM 的批调度要按“步对齐窗口”设计，而不是按请求队列长度设计</strong>。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-26\">二十六 · Chunked prefill 的类比：把调度表切段以压尾延迟</h3>\n<p>LLM 的 chunked prefill 把长 prompt 的预填切成小块，避免一个长请求独占一个迭代周期、把其他请求的 decode 步挤到后面。DDIM 没有 prefill/decode 的二分，但有一个结构同构的问题：<strong>调度表的步数 S 是单请求的总工作量，S 越大，该请求占用批的时间越长</strong>。若一个 S=50 的请求与一批 S=10 的请求同批，短请求跑完 10 步就空转等长请求，批利用率塌陷。解法是把调度表切段：将 S 步划分为若干 chunk，每个 chunk 结束时做一次批重组，短请求在 chunk 边界退出，长请求继续。这与 chunked prefill 的动机一致——用更细的调度粒度换取批内成员的周转率。</p>\n<p>代价是 chunk 边界引入额外的批重组开销与同步点。设 chunk 长度为 c 步，则单请求的批重组次数为 ⌈S/c⌉，每次重组要重新打包 x_t、时间步与提示嵌入。c 越小，尾延迟越低但重组开销占比越高；c 越大，吞吐越高但短请求被长请求拖尾。工程上 c 的选取要匹配 S 的分布：若请求的 S 集中在少数几个档位（例如 10/20/50），按档位分桶比按固定 c 切段更有效，因为同桶请求天然同步，不需要跨桶对齐。</p>\n<div class=\"formula\">$$\\text{批利用率} \\approx \\frac{\\sum_i S_i}{\\max_i S_i \\cdot n},\\quad \\text{尾延迟} \\propto \\max_i S_i \\cdot \\tau_{\\text{step}}$$</div>\n<p>其中 τ_step 为单步时延。这个式子给出一个直接判断：<strong>把长 S 请求与短 S 请求混批，批利用率按最长请求折算，尾延迟也按最长请求折算</strong>。因此 DDIM 服务的优先级设计不应只看请求到达顺序，还要看 S。具体例子：一个交互式出图前端默认 S=20，一个批量离线任务用 S=50 追求细节。若两者同批，交互请求的 P99 时延被离线请求拉长到 50 步的量级；正确做法是按 S 分池，交互池只跑 S≤20，离线池独立调度，两池之间用显存配额隔离而非混批。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-27\">二十七 · 优先级与抢占：确定性映射让抢占变得廉价</h3>\n<p>自回归服务的抢占要保存 KV cache 并重新计算被逐出的 token，代价高。DDIM 的抢占代价结构不同：确定性模式下 σ_t=0，转移是 x_t 到 x_{t-1} 的解析映射，<strong>抢占只需保存当前 x_t 与剩余调度点索引</strong>，恢复时从该点继续，不需要重放前序步骤，也不需要随机数状态。这是因为确定性采样把“隐变量到样本的映射”变成了可复现的确定性变换——同一 x_t 与同一调度点，在任何副本上给出同一 x_{t-1}。抢占的存储代价是每请求一个 x_t 张量加一个整数索引，而非整条噪声轨迹。</p>\n<p>但抢占有一个不可逆的代价：被抢占请求的<strong>批内合并机会丢失</strong>。恢复时若原批已推进到更晚的调度点，被抢占请求无法直接插回，只能等下一个步对齐窗口或单独起批。因此抢占策略要区分“可合并恢复”与“独立恢复”：前者等到批内步对齐，后者立即起小批但牺牲吞吐。优先级设计上，交互请求应获得“不抢占、只排队”的待遇，离线请求才允许被抢占，因为离线请求的 SLO 是吞吐而非尾延迟。</p>\n<p>具体例子：一个多租户出图服务，租户 A 付费用 SLO 约束 P99，租户 B 是批处理。调度器给 A 的请求打高优先级并预留批槽位，B 的请求在批满时被逐出，保存 x_t 与剩余步索引，等 A 的批出现空位再恢复。由于 DDIM 的抢占不重算前序步骤，B 的恢复开销只是重新打包，而非从头跑 S 步——这是确定性映射带来的直接工程收益。代价是 B 的完成时间被拉长，吞吐按被逐出次数打折。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-28\">二十八 · 分离式预填/解码的映射：提示编码与采样步解耦</h3>\n<p>LLM 的分离式预填/解码把计算密集的 prefill 与访存密集的 decode 放到不同资源池，按各自的最优批大小调度。DDIM 的可分离点不在“预填/解码”，而在<strong>提示编码与采样步之间</strong>：提示编码是一次性的文本编码器前向，输出条件嵌入；采样步是 S 次噪声预测前向，每步都要读条件嵌入。两者对资源的需求不同——编码器是短时高算力，采样步是长时稳定算力加激活带宽。把编码放在一个池、采样放在另一个池，可以让采样池的批大小不受编码器峰值干扰，也让编码池按到达率弹性伸缩。</p>\n<p>更细的分离点在 CFG 双分支：无条件分支与条件分支共享同一 x_t，但条件嵌入不同。若把两个分支拆到不同副本，需要同步 x_t，通信开销抵消收益；正确做法是同副本内合并为一次批前向，有效批大小翻倍。这与分离式解码的“同池合并”原则一致：<strong>能合批的分支不要拆池</strong>。分离的收益只在跨请求层面成立——把不同请求的采样步合批，而不是把同一请求的分支拆开。</p>\n<p>代价是跨池传输：编码池输出的条件嵌入要传到采样池，传输量是每请求一个嵌入张量，远小于 KV cache 的跨池传输。但采样池的批调度要等编码完成才能起批，引入一个编码时延的排队项。具体例子：一个高并发文本出图服务，编码池用大批量吞掉到达峰值，采样池按显存上限维持稳定批大小，两池之间用队列解耦。若编码池出现长尾（长提示），采样池会出现“批饥饿”，此时要么给编码池加副本，要么允许采样池用短提示请求先起批——后者要求调度器按提示长度分桶，与 chunked prefill 的分桶逻辑同构。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-29\">二十九 · 尾延迟怎么压：步对齐、分桶与最小步数下限</h3>\n<p>DDIM 服务的尾延迟来源有三个，且都与 S 相关。第一是<strong>批内最长 S 拖尾</strong>：混批时 P99 由最长请求决定，压尾延迟的第一手段是按 S 分桶，让同桶请求同步推进。第二是<strong>步对齐等待</strong>：新请求到达时若错过当前调度点，要等到下一步才能入批，等待时间是一个 τ_step 的量级；S 越小、τ_step 占比越大，对齐等待越显著。第三是<strong>低步数质量回归导致的隐式重试</strong>：步数压得过低时细节崩坏，前端可能触发重试，重试请求重新排队，尾延迟被放大。第三点不是调度能解决的，要靠 SLO 设最小步数下限，把质量约束前置到调度参数里。</p>\n<p>压尾延迟的具体机制是“预留槽位 + 步对齐窗口”：调度器为高优先级请求预留固定批槽位，新请求在窗口内到达即插即用，窗口外则等下一调度点。窗口长度取 τ_step 的整数倍，窗口越长对齐等待越短但批利用率越低。设窗口为 w 步，则批利用率损失约为 w/S 的量级——S=20、w=2 时损失约一成，S=10 时损失约两成。这个折算说明：<strong>低 S 请求的尾延迟优化空间被批利用率挤压</strong>，交互式服务要在 S 与窗口之间做联合取舍，而不是单独调窗口。</p>\n<p>具体例子：一个 S=10 的交互服务，τ_step 为单步时延，窗口取 2 步则对齐等待最多 2τ_step，批利用率损失约两成；若把 S 提到 20，同样窗口的利用率损失降到一成，但单请求前向次数翻倍、单请求延迟翻倍。工程判断是：<strong>交互场景优先压 S 而非压窗口</strong>，因为 S 直接决定单请求延迟的下限，窗口只影响排队项；而离线场景相反，优先压窗口保吞吐，S 可以取大以换质量。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-30\">三十 · 调度参数与容量规划的耦合：S 是服务参数不是模型参数</h3>\n<p>DDIM 把采样步数变成可调服务参数，这意味着容量规划的自变量从“模型固定工作量”变成了“S 的分布”。设请求到达率为 λ、平均步数为 S̄、单步时延为 τ_step，则单副本的吞吐上限约为 n_max/(S̄·τ_step)（n_max 为显存折算的并发上限）。这个式子里的三个量都可调：n_max 由显存与单步激活决定，S̄ 由质量 SLO 决定，τ_step 由算子与精度决定。容量规划要做的是在这三者之间找可行域，而不是按固定模型工作量算副本数。</p>\n<p>耦合点在于 S 与质量的权衡不是线性的：步数压缩会放大单步误差，高噪声段与低噪声段的调度点选取直接影响低步数下的细节质量。调度器若为了吞吐把 S 压到下限以下，质量回归会以重试或投诉的形式反噬吞吐。因此容量规划要留出“质量余量”：S 的下限由 SLO 定，上限由延迟预算定，调度器只在区间内调节，不越界。这与 LLM 服务里“上下文长度上限由显存定、由 SLO 约束”的逻辑同构——<strong>可调参数必须有硬边界，否则调度器会用吞吐换质量</strong>。</p>\n<p>具体例子：一个出图服务的延迟预算给出 S≤20，质量 SLO 给出 S≥10，则调度器在 10–20 之间按负载调节：低负载取 20 保质量，高负载取 10 保吞吐。这个区间内的吞吐变化按 1/S̄ 线性折算，容量规划按区间上界的 S̄ 配置副本数以覆盖峰值，按区间下界评估质量风险。论文未给出吞吐与显存数据，因此这个折算只能定性成立——步数与前向次数的线性关系是机制层面的确定结论，但把它换算成端到端吞吐提升需要实测 τ_step 与批利用率，不能直接外推。</p>\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-31\">三十一 · 并行切分的四个轴与扩散推理的真实负载</h3>\n<p>DDIM 的推理负载有一个容易被并行方案忽略的性质：单请求的前向次数等于调度表长度 S，而每次前向的激活规模由批大小与分辨率决定，两者相乘构成单请求的算力占用。把这条负载拆到多卡上，TP、EP、PP、DP 四个轴的选择并不对称。TP 切的是单层内部的矩阵乘，每层一次前向要两次 All-Reduce（注意力输出投影与 MLP 下投影各一次），通信量与批大小和隐藏维成正比，与层数无关；PP 切的是层间流水，只在阶段边界传激活，通信量小但引入流水气泡，气泡占比约等于 (PP-1)/microbatch 数；EP 切的是 MoE 或专家分支，每层一次 All-to-All，通信量随 token 数与专家并行度增长；DP 复制权重、切分请求，只在梯度或参数同步时需要集合通信，纯推理下几乎无通信，代价是每张卡都持有完整权重。</p>\n<p>对 DDIM 这类每步只做一次噪声预测前向的模型，单步延迟由最慢的那个并行阶段决定。设单步计算时间为 T_comp、单次集合通信时间为 T_comm，则 TP 组内的单步延迟近似为</p>\n<div class=\"formula\">$$T_{step}\\approx T_{comp}+2\\,T_{comm}^{AR},\\qquad T_{comm}^{AR}\\approx \\frac{2\\,(N-1)}{N}\\cdot\\frac{B\\cdot H\\cdot b}{W}$$</div>\n<p>其中 N 为 TP 度、B 为批大小、H 为隐藏维、b 为字节宽度、W 为链路带宽。这个式子说明：批越小，All-Reduce 的相对开销越大，TP 度越高越不划算。扩散推理在小批、低延迟场景（单张图、S 很小）下，TP 的通信占比会迅速压过计算收益。一个具体例子：8 卡 TP=8 跑单请求单步前向，每层两次 All-Reduce，隐藏维数千量级，单次通信在微秒级，但层数几十层累加后，通信时间可与计算时间同量级，此时把 TP 降到 2、把剩余卡划给 DP 反而降低单步延迟。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-32\">三十二 · NVLink 5 与 NVSwitch：域内带宽把通信从瓶颈推回计算</h3>\n<p>Blackwell 世代的 NVL72 机柜把 72 个 GPU 放进同一个 NVLink 域，NVLink 5 的每 GPU 双向带宽与 NVSwitch 的全互联拓扑，使得域内 All-Reduce 与 All-to-All 不再需要走 PCIe 或跨节点网络。对 DDIM 推理而言，这条链路改变的是并行方案的经济性：TP 度可以跨 8 卡甚至更大而不至于让通信成为单步延迟的主项，EP 的 All-to-All 可以在机柜内完成一次完整的 token 置换而不落回主机内存。工程判断的落点是——只要并行组落在同一个 NVLink 域内，集合通信的代价主要由协议栈与 kernel 启动决定，而非物理带宽；一旦并行组跨越域边界，同样的 All-Reduce 就要经过网卡与交换机，延迟抬升一个量级，此时并行策略必须重排。</p>\n<p>代价体现在功耗与占用上：NVSwitch 全互联意味着任意两块卡之间的通信不经过转发跳数，但交换芯片本身有固定功耗预算，机柜级部署要把这部分算进每 token 的能耗。另一个具体机制是集合通信的算法选择：小消息用 ring 还是 tree、大消息用 NVLS（NVLink SHARP）做网内归约，直接决定 All-Reduce 是占用带宽还是占用 SM。NVLS 把归约下推到交换机，SM 侧只做收发，对 DDIM 这种每步都要做多次 All-Reduce 的负载，等于把通信从计算核上卸载，单步延迟的抖动随之下降。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-33\">三十三 · All-to-All 与 NIXL：EP 的代价与跨节点传输</h3>\n<p>EP 在扩散推理里出现的场景是专家分支或条件分支的稀疏化。每层一次 All-to-All，token 按路由结果重排到持有对应专家的卡上，算完再 All-to-All 换回。通信量正比于 token 数乘以隐藏维乘以字节宽度，且是双向的两次置换。设每层 token 数为 M、专家并行度为 E，则单层 All-to-All 的传输量为</p>\n<div class=\"formula\">$$V_{A2A}\\approx 2\\cdot\\frac{E-1}{E}\\cdot M\\cdot H\\cdot b$$</div>\n<p>这个量随 E 增大趋近饱和，但随 M 线性增长，因此 EP 在大批、高吞吐场景下摊薄得好，在小批低延迟场景下则是纯开销。DDIM 的批内样本共享同一时间步，批越大单步算力利用率越高，这与 EP 的摊薄逻辑一致；但确定性采样要求每个请求分配不同隐变量，批的组成是请求驱动的，不能为了 EP 效率无限堆批。</p>\n<p>跨节点传输由 NIXL 承担。NIXL 提供的是点对点的异步数据传输抽象，把显存到显存、显存到存储的搬运从集合通信里解耦出来。在分离式预填/解码或 KV 类状态迁移的场景里，NIXL 让传输与计算重叠：解码侧在等传输的同时可以继续跑当前步的前向。对 DDIM，虽然它不保留 KV 缓存，但批内隐变量与调度表状态在多副本间迁移、结果缓存回填这类动作，同样适合走 NIXL 的点对点路径而非集合通信。代价是传输层引入额外的描述符管理与完成队列轮询，小消息下这部分开销可能超过数据本身，因此迁移粒度要按块而非按张量切。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-34\">三十四 · 通信何时成为瓶颈：三个判据</h3>\n<p>第一个判据是计算通信比。单步内计算时间与集合通信时间之比低于某个阈值时，增加并行度不再缩短单步延迟。对 TP，这个阈值由批大小决定：批越小，计算时间越短，通信占比越高。DDIM 的低步数模式恰恰是小批、短计算的组合，因此 TP 度在低延迟服务里应保守取值。</p>\n<p>第二个判据是并行组是否跨域。NVLink 域内的 All-Reduce 与跨域 All-Reduce 在延迟上差一个量级，一旦 TP 或 EP 组跨越机柜边界，单步延迟的构成就从计算主导变为通信主导。工程上的做法是把 TP 与 EP 约束在域内，把 PP 与 DP 放到域间，因为 PP 只在阶段边界传激活、DP 纯推理几乎不通信，两者对跨域延迟不敏感。</p>\n<p>第三个判据是流水气泡。PP 的气泡占比约等于 (PP-1)/microbatch 数，DDIM 的 S 步是串行链，microbatch 只能来自批内切分，批小则气泡无法摊薄。一个具体例子：PP=4、批内切 2 个 microbatch，气泡占比接近 3/2 量级，单请求延迟反而高于 PP=1；只有当批大到能切出足够多的 microbatch 时，PP 才开始划算。</p>\n<table class=\"mini\"><thead><tr><th>并行轴</th><th>通信原语</th><th>通信量随什么增长</th><th>DDIM 下的适用判断</th></tr></thead><tbody><tr><td>TP</td><td>每层两次 All-Reduce</td><td>批大小 × 隐藏维</td><td>大批高吞吐适用；小批低延迟慎用</td></tr><tr><td>EP</td><td>每层两次 All-to-All</td><td>token 数 × 隐藏维 × 并行度</td><td>需大批摊薄，且约束在 NVLink 域内</td></tr><tr><td>PP</td><td>阶段边界点对点</td><td>microbatch 数 × 激活规模</td><td>批小则气泡主导，通常不划算</td></tr><tr><td>DP</td><td>纯推理无集合通信</td><td>—</td><td>复制权重换吞吐，显存是约束</td></tr></tbody></table>\n<p>显存侧的代价同样要计入：TP 与 EP 切分权重，单卡权重占用下降，但激活与通信缓冲上升；DP 复制权重，单卡权重占用不降。DDIM 不保留 KV 类缓存，显存大头是权重与单步激活，因此 TP/EP 的显存收益主要体现在权重上，而通信缓冲的增量在小批下不可忽略。功耗侧，集合通信把 SM 从计算态拉进收发态，NVLS 卸载能缓解但不能消除，机柜级容量规划要把通信功耗算进每 token 预算。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-35\">三十五 · 把并行拓扑绑到调度表上</h3>\n<p>DDIM 把采样步数变成可调服务参数，这一条直接改写并行策略的选取逻辑。步数 S 小，单请求前向次数少，单步延迟权重高，并行方案应向低通信、低气泡倾斜：TP 度压低、PP 关闭、DP 扩到显存允许的上限，用副本数换并发。步数 S 大或批很大，单步计算时间被拉长，通信占比下降，TP 与 EP 的摊薄效应显现，此时提高 TP 度、把 EP 约束在 NVLink 域内是合理选择。</p>\n<p>调度表与并行拓扑的耦合点在于批内步数一致性。批内所有样本共享同一时间步，若不同副本的调度表不一致，批就无法合并前向，并行度再高也换不来吞吐。工程实现上要把调度表作为请求元数据随批下发，保证同一批内 S 与时间子序列完全相同，这样 TP 组内的 All-Reduce 才对同一个批生效。确定性模式 σ_t=0 带来的可复现性在这里有直接价值：同一隐变量在任意副本上输出一致，副本间的结果比对与缓存回填不需要额外的一致性协议，DP 扩副本的代价仅限于显存而非正确性校验。</p>\n<p>最后落在具体机制上：并行拓扑的选择应随 S 与批大小动态调整，而不是部署时一次定死。低步数、小批的请求走 DP 为主的拓扑，把 TP 压到 1 或 2；高步数、大批的请求走 TP 与 EP 混合、约束在 NVLink 域内的拓扑。切换的判据就是前面那条计算通信比——单步计算时间除以集合通信时间，低于阈值就减并行度、加副本数，高于阈值就反向操作。这条判据不需要实验数字支撑，只需要在运行时采样单步耗时与通信耗时，把比值作为调度器的输入信号。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-36\">三十六 · 确定性采样下的并行拓扑边界与通信代价</h3>\n<p>DDIM 把单请求前向次数压到 S 次之后，并行切分的瓶颈从计算转向通信。TP 切分每层权重与激活，每步前向内部要插两次 All-Reduce；EP 把不同专家放到不同卡上，token 路由产生 All-to-All；PP 沿层切分，微批在 stage 间走点对点激活传递；DP 复制权重、切分请求。对扩散推理而言，关键约束是批内所有样本共享同一时间步调度，因此 PP 的流水填充必须让同一微批跨 stage 同步推进，任一 stage 的 All-Reduce 延迟都会直接叠加到单步时延上，S 步就是 S 次这样的叠加。NVLink 5 与 NVSwitch 提供机柜内高带宽全互联，使 TP 的 All-Reduce 与 EP 的 All-to-All 在 NVL72 域内代价可控；跨机柜则退化为 RDMA 路径，NIXL 负责把 KV 与激活块在节点间搬运，此时通信开始主导。</p>\n<p>通信是否成为瓶颈，可用单步计算与通信的时间比判断。设单步前向计算量为 C、单卡算力为 F、通信量为 M、有效带宽为 B，则单步时间近似为</p>\n<div class=\"formula\">$$T_{\\text{step}}\\approx \\frac{C}{F\\cdot \\eta_{\\text{mma}}}+\\frac{M}{B\\cdot \\eta_{\\text{net}}},\\qquad \\text{加速上限}=\\frac{S\\cdot C/F}{S\\cdot T_{\\text{step}}}$$</div>\n<p>其中 η_mma 反映 tcgen05 与 2-SM MMA 的利用率，η_net 反映集合通信效率。当 M/B 项与 C/F 项同量级时，增加切分度不再缩短单步时间，反而因更细粒度集合通信抬高固定开销。具体例子：EP 专家并行下，每步每个 token 需两次 All-to-All（派发与回收），若专家切分过细导致每卡 token 数低于 MMA 的 tile 粒度，计算侧无法填满 TMEM，通信却按 token 数线性增长，此时 EP 度数的收益被通信吞掉。确定性 DDIM 的批内同步特性放大了这一点：一个慢 stage 会拖住整批，无法像训练那样靠异步梯度掩盖。</p>\n<table class=\"mini\"><thead><tr><th>切分方式</th><th>每步通信形态</th><th>失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>TP</td><td>层内 All-Reduce</td><td>切分度高、单卡计算不足以掩盖通信</td><td>单步时延随 S 线性叠加</td></tr><tr><td>EP</td><td>token All-to-All</td><td>每卡 token 低于 tile 粒度</td><td>带宽占用升、MMA 利用率降</td></tr><tr><td>PP</td><td>stage 间点对点</td><td>微批不足、流水填充空转</td><td>气泡计入每步关键路径</td></tr><tr><td>DP</td><td>无（权重复制）</td><td>显存不足以容纳副本</td><td>显存换吞吐，无通信收益</td></tr></tbody></table>\n<p>工程判断落在两处：一是把 TP 与 EP 限制在 NVLink 域内，跨域只走 PP 或 DP，避免 All-Reduce 落到 RDMA 上；二是按 S 与批大小反推切分度，使每步通信时间不超过计算时间的固定比例。CFG 双分支使有效批翻倍，激活显存与单步通信量同步上升，需在并发与切分度之间做显存折算。步数压得越低，单步时延占比越高，通信固定开销越难摊薄——这正是少步采样与并行拓扑之间的真实边界。</p>\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-37\">三十七 · 精度塌陷：低步数下的误差累积与数值放大</h3>\n<p>DDIM 把单请求前向次数从数百压到数十，收益是线性的，但代价也线性地压在了每一步上。非马尔可夫转移把每步的 <span class=\"inline-math\">ε_θ(x_t,t)</span> 解析地折算成 <span class=\"inline-math\">x̂_0</span>，再组合出 <span class=\"inline-math\">x_{t-1}</span>；当调度子序列 <span class=\"inline-math\">t_1&gt;…&gt;t_S</span> 变稀疏时，相邻调度点之间的 <span class=\"inline-math\">α_t</span> 跨度变大，单步系数 <span class=\"inline-math\">√(1−α_{t-1}−σ_t²)</span> 与 <span class=\"inline-math\">√α_{t-1}</span> 的动态范围被拉宽，任何一步的噪声预测偏差都会被后续解析式原样放大，而不是像马尔可夫链那样被逐级注入的随机噪声稀释。</p>\n<div class=\"formula\">$$\\hat{x}_0^{(t)}=\\frac{x_t-\\sqrt{1-\\alpha_t}\\,\\epsilon_\\theta(x_t,t)}{\\sqrt{\\alpha_t}},\\qquad x_{t-1}=\\sqrt{\\alpha_{t-1}}\\,\\hat{x}_0^{(t)}+\\sqrt{1-\\alpha_{t-1}-\\sigma_t^2}\\,\\epsilon_\\theta(x_t,t)+\\sigma_t\\epsilon$$</div>\n<p>诊断上要区分两类塌陷：一是<b>结构性塌陷</b>，即调度点未覆盖高噪声段或低噪声段两端，表现为整体构图崩坏、色彩块状化；二是<b>数值性塌陷</b>，即低精度下 <span class=\"inline-math\">x̂_0</span> 的除法与开方在 <span class=\"inline-math\">α_t</span> 接近 0 时放大舍入误差，表现为高频纹理糊化、边缘出现周期性条纹。前者靠调度表审查定位，后者靠逐步骤残差比对定位：把同一隐变量在 FP32 与部署精度下各跑一遍，记录每步 <span class=\"inline-math\">‖x̂_0^{(t)}−x̂_0^{(t),ref}‖</span>，若误差在某几个调度点上跳变而非均匀增长，即为系数实现问题而非模型问题。工程代价上，精度塌陷不会报错，只会让质量指标缓慢劣化，因此必须把最小步数下限写进 SLO 而非交给调用方自由设定。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-38\">三十八 · OOM：批内双分支与激活峰值</h3>\n<p>DDIM 本身不保留噪声轨迹，显存里只有当前 <span class=\"inline-math\">x_t</span> 与网络激活，KV 类缓存不适用；但 CFG 让批内每个请求变成双分支前向，有效批大小为请求数乘以分支数。显存峰值出现在单步前向的激活张量上，随有效批线性增长：<span class=\"inline-math\">M_peak ≈ B_req·2·A_step + B_req·2·|x_t|</span>，其中 <span class=\"inline-math\">A_step</span> 是单样本单步激活规模。调度器若按请求数而非有效样本数折算并发，就会在 CFG 打开时把显存打穿。</p>\n<p>OOM 的定位要区分三种来源：批配置超限（并发数乘以分支数超过显存折算上限）、单步激活尖峰（某些时间步的注意力序列更长或分辨率更高）、以及碎片化（长请求与短请求混跑导致显存池无法复用）。前两种靠准入控制解决，第三种靠把批内步数对齐、按 S 分桶调度解决。具体例子：一批 8 个请求、CFG 双分支，有效样本 16；若单样本单步激活占显存 <span class=\"inline-math\">A_step</span>，则峰值约为 <span class=\"inline-math\">16·A_step</span> 加上隐变量本身，调度器必须在入队时用这个折算值做准入，而不是用 8。代价是吞吐：CFG 双分支让有效批翻倍，显存换吞吐的折算比例直接决定并发上限，这也是 DDIM 部署里最容易被低估的一项。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-39\">三十九 · 批抖动与尾延迟：步数不一致的连锁反应</h3>\n<p>DDIM 的批调度前提是批内样本共享同一时间步调度。一旦允许不同请求用不同 S，批内步数就不一致，短请求先完成、长请求继续占用批槽，形成<b>批抖动</b>：每步前向的有效利用率下降，尾延迟被最长请求拖住。更隐蔽的是调度点不一致——两个请求 S 相同但子序列选取不同，就无法合并前向，只能拆批，拆批又带来显存与通信的额外开销。</p>\n<p>尾延迟的根因通常不在单步计算，而在<b>队列等待与批重组</b>。连续批处理下，一个 S=50 的请求和一个 S=20 的请求同批，前者要走完 50 步，后者在第 20 步后空转占槽，等效于把短请求的延迟拉长到长请求的水平。定位方法是按请求记录 <span class=\"inline-math\">t_queue</span>、<span class=\"inline-math\">t_first_step</span>、<span class=\"inline-math\">t_last_step</span> 三段，若 <span class=\"inline-math\">t_last_step−t_first_step</span> 远大于 <span class=\"inline-math\">S·t_step</span>，说明批内被长请求拖拽；若 <span class=\"inline-math\">t_queue</span> 占比高，则是准入与分桶策略问题。工程判断是：把 S 分桶、桶内共享调度表，用桶级并发上限替代全局并发上限，牺牲少量批利用率换尾延迟的可预测性。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-40\">四十 · 静默降级：确定性模式下的多样性损失与缓存陷阱</h3>\n<p>σ_t=0 的确定性采样让同一隐变量与提示在任意副本上输出一致，这既是重试与缓存的基础，也是静默降级的温床。批量服务若为省事给一批请求复用同一隐变量，确定性模式下会得到一批完全相同的图——系统不报错、指标不报警，但业务侧看到的是多样性归零。这类降级只能靠<b>输出指纹监控</b>发现：对每批输出计算感知哈希或嵌入距离，若批内两两距离低于阈值且持续出现，判定为隐变量复用或种子分配错误。</p>\n<p>缓存陷阱是另一类：确定性映射可逆、可复现，于是有人把 <span class=\"inline-math\">(prompt, x_T)</span> 到输出的映射做成结果缓存。但缓存键若漏掉步数 S、调度表版本或 CFG 强度，就会在参数变更后返回旧结果，表现为“改了配置但输出没变”的静默降级。定位靠版本化缓存键：把 S、调度表哈希、σ_t 取值、CFG scale 全部纳入键，任一变更即失效。代价是缓存命中率下降，但换来的是配置变更的可观测性。定性判断是：确定性带来的可复现性是双刃剑，它让缓存成为可能，也让错误配置的后果被完整复现而非被随机性掩盖。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-41\">四十一 · 监控与回滚：把采样参数纳入发布单元</h3>\n<p>监控面要覆盖三层：<b>请求层</b>记录 S、σ_t、CFG scale、调度表版本与输出指纹；<b>批层</b>记录有效批大小、批内步数方差、拆批次数与显存峰值；<b>质量层</b>用固定隐变量集做金丝雀回归，比对低步数与参考步数下的输出距离。三层缺一层，塌陷就会从某一层漏过去。诊断顺序建议自下而上：先看批层是否抖动或 OOM，再看请求层参数是否越界，最后看质量层是否漂移。</p>\n<p>回滚的关键是把采样调度表当作独立发布单元，而不是随模型权重一起发。DDIM 零重训即可切换采样器，意味着调度表、系数实现、σ_t 取值都可以单独回滚：发现低步数质量回归时，把最小步数下限调回上一档；发现系数实现引入数值塌陷时，回滚到上一版调度表哈希；发现缓存键漏项时，直接清空缓存并升版本号。代价是发布流程变复杂，但换来的是故障域隔离——采样器的问题不会倒逼模型权重回滚，反之亦然。具体机制上，调度表以内容哈希标识并随请求打点上报，回滚即切换哈希指针，金丝雀流量按哈希分流比对，确认质量恢复后再全量。</p>\n<p>最后落在工程判断上：DDIM 的失败模式几乎全部是<b>参数性</b>而非<b>崩溃性</b>的——步数、σ_t、批折算、缓存键，任一项配错都不会抛异常，只会让质量或延迟缓慢偏离。因此部署侧的核心不是加更多告警，而是把采样参数与调度表版本变成可观测、可回滚的一等发布对象，让每一次“变慢”或“变糊”都能追到具体的那一个系数。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-42\">四十二 · 确定性采样的失效边界：从数值塌陷到批级尾延迟的定位与回滚</h3>\n<p>DDIM 的确定性转移把随机项彻底移除，这一步在数学上换来可复现性，在工程上却把误差的容错空间一并收走。马尔可夫链里每步注入的噪声实际上是一种隐式正则：它把单步预测的偏差打散、稀释，让后续步有机会纠偏。取 σ_t=0 后，转移变为 <span>$$x_{t-1}=\\sqrt{\\alpha_{t-1}}\\,\\hat{x}_0+\\sqrt{1-\\alpha_{t-1}}\\,\\epsilon_\\theta(x_t,t)$$</span> 的纯解析组合，任何一步的 ε_θ 偏差都会原样进入 x_{t-1}，并在剩余步数里被反复放大。步数 S 越少，单步跨越的时间间隔越大，这种放大越剧烈，表现为高噪声段调度点稀疏时整体构图漂移、低噪声段调度点稀疏时高频纹理崩坏。诊断上不能只看最终图，要在每个调度点记录 ‖x̂₀ − x₀_ref‖ 之类的中间量（用高步数同隐变量结果作参考），一旦某步的相对偏差超过阈值就说明该段调度点密度不足。代价是显式的：把 S 从数十提到更高来压误差，单请求前向次数线性回升，延迟与显存占用同步上升，等于用吞吐换质量，这条曲线必须在 SLO 里写死最小步数下限而不是让调度器自由下探。</p>\n<p>批级失败里最隐蔽的是批抖动与静默降级。批内样本共享同一时间步调度，一旦某个请求因重试或缓存命中被替换了隐变量，或 CFG 双分支前向的有效批大小按请求数×分支数折算后超出显存预算，就会出现部分样本走完 S 步、部分样本被截断提前出图的情况——服务不报错，返回的图像却是低步数产物，这就是静默降级。定位手段是把批内步数一致性做成硬指标：每批记录实际执行步数与请求声明步数的比值，任何小于 1 的批直接打标并抽样人工核验。OOM 则多发生在 CFG 双分支叠加长提示编码的峰值时刻，单步激活规模随批线性增长，按显存折算并发时若只算请求数不算分支数，峰值必爆；对策是把有效批大小写成 <span>$$\\text{batch}_{\\text{eff}}=\\text{req}\\times\\text{branches}\\times\\text{activation}_{\\text{per-sample}}$$</span> 并在准入层拦截，而不是等运行时 OOM 再回滚。尾延迟的根因通常是批内最慢样本拖着整批等最后一步，确定性模式下无法用随机重采样掩盖，只能靠拆分长短请求队列解决。</p>\n<p>监控与回滚要围绕“可复现”这一唯一优势设计。既然同一隐变量与提示在任意副本上输出一致，就可以用固定隐变量探针做在线金丝雀：每隔固定请求数插入一条已知隐变量的探针请求，比对输出与基线副本的逐像素差异，差异超阈值即判定该副本的采样调度或数值精度发生了漂移（低精度量化会直接体现为这种漂移）。回滚粒度应落在调度表而非模型权重上——因为切换采样器是零重训的推理替换，回滚只需把调度表与 σ_t 系数换回上一版本，权重不动，回滚窗口以秒计而非以小时计。需要警惕的是把 DDIM 的步数收益直接换算成吞吐承诺：材料未给出量化与显存数据，步数与前向次数的线性关系只保证延迟侧的可预期性，吞吐还受批调度粒度与 CFG 分支开销牵制，容量规划里必须把这两项单独建模，否则一次调度表回滚就会连带打破已承诺的吞吐水位。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>可观测信号</th><th>定位手段</th><th>回滚动作</th></tr></thead><tbody><tr><td>精度塌陷</td><td>中间 x̂₀ 偏差超阈、纹理崩坏</td><td>逐调度点比对高步数参考</td><td>提高最小步数、加密调度点</td></tr><tr><td>OOM</td><td>峰值显存触顶</td><td>按有效批大小折算并发</td><td>降并发、拆 CFG 分支</td></tr><tr><td>批抖动/静默降级</td><td>批内步数一致性 &lt; 1</td><td>批级步数打标抽样</td><td>换回上一版调度表</td></tr><tr><td>尾延迟</td><td>批完成时间被最慢样本拖长</td><td>长短请求分队列</td><td>拆批、缩短批窗口</td></tr></tbody></table>\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-43\">四十三 · 论文口径与可核验边界</h3>\n<p>读这篇论文的任何性能段落之前，先确认一件事：它给的是采样机制的可行性论证，不是服务端基准报告。材料中明确缺失的量包括数据集规模、FID 数值、硬件档位、并行拓扑、量化方案与吞吐/显存实测。这意味着凡是把 DDIM 的“步数减少”直接换算成“QPS 提升 N 倍”的说法，都属于口径外推。可核验的只有一条硬关系：单请求前向次数等于所选步数 S，而原马尔可夫采样必须走完预设的数百至上千步。因此延迟的一阶模型可以写成</p>\n<div class=\"formula\">$$T_{\\text{req}} \\approx S \\cdot \\left(t_{\\text{fwd}}(B_{\\text{eff}}) + t_{\\text{coef}}\\right) + T_{\\text{post}}$$</div>\n<p>其中 <em>t</em><sub>fwd</sub> 是单次批前向耗时，随有效批大小 <em>B</em><sub>eff</sub> 变化；<em>t</em><sub>coef</sub> 是解析组合 x0 与 x<sub>t−1</sub> 的逐元素开销，在 Blackwell 上属于纯访存受限的轻量 kernel；<em>T</em><sub>post</sub> 是解码器还原图像的时间。这个式子的价值不在于估出绝对数字，而在于指出哪些项在论文里有依据（S 的线性），哪些项必须自己实测（<em>t</em><sub>fwd</sub> 的批 scaling、解码器占比）。论文只覆盖第一项。</p>\n<p>第二个口径问题是基线。论文的对照是同一预训练权重下的马尔可夫反向链，属于“同模型、换采样器”的受控比较，这一点是它最扎实的地方：网络、训练目标、权重全部不变，差异只来自调度表与方差参数。反过来说，任何拿 DDIM 与另一个重新训练过的少步模型对比的数字，都不属于这篇论文的口径。工程上判断一个 DDIM 加速比是否可比，只需问三句：权重是否同源、步数是否在同一质量约束下比较、随机性设置是否一致。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-44\">四十四 · 硬件档位：步数收益在什么机器上才兑现</h3>\n<p>DDIM 把负载从“长链小步”改成“短链大步”，这个变换对硬件的偏好非常具体。原马尔可夫采样每步只做一次噪声预测，步间串行、批内可合并，属于典型的低算术强度、高 kernel 启动频率的负载；步数压缩后单请求前向次数下降，但每次前向的批规模可以做大，算术强度上升。在 B200/B300 这类 SM100 档位上，这意味着两件事：一是 kernel 启动与调度开销在总延迟中的占比下降，收益更容易兑现；二是单步激活的显存峰值成为新的约束，因为批做大之后激活规模随批线性增长。</p>\n<p>反过来，在小显存档位或 MIG 切分的实例上，DDIM 的步数收益会被两件事吃掉：CFG 双分支使有效批翻倍，激活峰值提前撞墙，只能降并发；解码器（VAE 或等效还原模块）在低步数下占总延迟的比例上升，因为分子变小了。一个具体例子：同一张卡上，S 从数百降到数十，前向部分的理论耗时按比例缩小，但如果解码器耗时不变，端到端延迟的下降幅度会明显小于步数下降幅度——这是把步数收益误读为端到端收益的最常见来源。判断方法是先测解码器占比，再决定是否值得为步数压缩投入调度改造。</p>\n<p>材料未给出并行拓扑，因此不能假设张量并行或专家并行的切分方式。工程判断上，DDIM 的批内样本共享同一时间步调度，这使它对并行切分不敏感——不像自回归解码那样有 KV 长度异构问题——但也意味着它无法从序列维并行中获益，只能从批维和数据并行中获益。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-45\">四十五 · batch、并发与有效批的折算</h3>\n<p>论文层面只提到“按批合并做前向”和“CFG 需双分支前向，批大小应按显存折算为有效样本数再定并发”。把这句话展开成可执行的折算规则：设请求批为 <em>N</em><sub>req</sub>，CFG 分支数为 <em>k</em>（通常 2），则有效批 <em>B</em><sub>eff</sub> = <em>N</em><sub>req</sub> · <em>k</em>。单步激活显存近似正比于 <em>B</em><sub>eff</sub> 乘以单样本单步激活量，再加上模型权重与工作区。于是并发上限由</p>\n<div class=\"formula\">$$N_{\\text{req}}^{\\max} \\approx \\left\\lfloor \\frac{M_{\\text{free}} - M_{\\text{w}} - M_{\\text{ws}}}{k \\cdot m_{\\text{act}}(S)} \\right\\rfloor$$</div>\n<p>给出，其中 <em>m</em><sub>act</sub>(S) 与步数相关：步数少时无需保留长噪声轨迹，只需当前 x<sub>t</sub> 与网络激活，这正是 DDIM 相对马尔可夫链在显存上的结构性优势——后者需保留完整噪声轨迹。但要注意，这个优势是“轨迹不保留”，不是“激活不增长”；批做大仍然线性吃显存。</p>\n<p>具体例子：在固定显存预算下，若把 S 减半，单请求占用时长减半，理论上可服务请求数翻倍；但若同时把批翻倍以提升吞吐，激活峰值也翻倍，两者会互相抵消，最终并发由显存而非步数决定。这就是为什么“步数少所以并发高”不是自动成立的推论。工程上的正确做法是固定 <em>B</em><sub>eff</sub> 先测单步耗时曲线，找到吞吐拐点后再调 S，而不是先调 S 再猜并发。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-46\">四十六 · 指标口径：TTFT/TPOT 在扩散负载上的映射</h3>\n<p>TTFT 与 TPOT 是自回归解码的术语，直接套到扩散上会失真。扩散请求没有“首 token”概念，但有等价的两个量：首帧可见时间（第一个可解码样本出现的时间）与每步推进时间。对 DDIM 而言，前者近似等于“调度表首段若干步 + 解码器启动”，后者等于单步前向加系数组合。更贴合的口径是：</p>\n<ul>\n<li>单请求延迟 = S · 单步耗时 + 解码耗时，其中单步耗时随 <em>B</em><sub>eff</sub> 变化；</li>\n<li>吞吐 = 完成请求数 / 时间，受批调度粒度与步数共同约束；</li>\n<li>显存峰值 = 权重 + 工作区 + <em>k</em> · <em>N</em><sub>req</sub> · 单样本单步激活；</li>\n<li>功耗与带宽：低步数下单位时间前向次数下降，但批做大后单次前向的带宽占用上升，两者对功耗的净效应需实测，论文未给。</li>\n</ul>\n<p>这里有一个容易被忽略的口径陷阱：确定性模式（σ<sub>t</sub>=0）不消耗随机数，因此同一隐变量与提示在任意副本上输出一致，可支持重试、缓存与结果比对。这让“缓存命中率”成为一个有意义的服务指标——相同提示加相同隐变量的请求可直接复用结果，降低重复计算。但代价是样本多样性下降，批量服务必须为每请求分配不同隐变量，否则整批输出雷同。于是缓存收益与多样性损失构成一对必须一起报的口径，只报缓存命中率不报多样性，等于选择性披露。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-47\">四十七 · 哪些提升不可比：四类常见误读</h3>\n<p>第一类，跨权重比较。DDIM 的加速来自“同权重换采样器”，若对照组是重训过的少步模型，则步数差异混入了训练差异，不可比。第二类，跨质量约束比较。论文明确说步数减少时质量下降比马尔可夫采样更平缓，但具体步数与 FID 未给出；因此“S=10 与 S=50 谁更好”这类问题在论文口径内无答案，只能在自己的数据上做质量回归。第三类，把前向次数收益当成端到端收益，忽略了系数组合 kernel 与解码器的固定开销。第四类，把确定性带来的可复现性当成吞吐收益——可复现降低的是重试与缓存成本，不是单次前向成本。</p>\n<p>还有一类更隐蔽的：方差参数 σ<sub>t</sub> 介于 0 与马尔可夫链对应值之间时可折中随机性与质量，这意味着“同一 S 下不同 σ”本身就是不同的负载配置。把 σ=0 的延迟数字与 σ 取中间值的质量数字拼在一起报，是口径混用。工程上应把 (S, σ) 作为一个二维配置点记录，任何性能数字都绑定在这对参数上。</p>\n<p>具体例子：若某团队报告“步数降到 1/10、延迟降到 1/8”，差额的那部分正是系数组合与解码器的固定开销；若再报告“质量持平”，必须同时给出 σ 取值与调度点选取方式，否则无法判断是机制收益还是配置调参。论文的消融只做了 σ 的定性对比，未给数值，这正是它作为机制论文而非基准论文的定位。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-48\">四十八 · 落到工程判断：先建口径表再谈加速</h3>\n<p>把这篇论文用于容量规划时，正确的顺序是先建一张口径表，再谈加速比。表里至少要有：权重来源（同源/重训）、S 与 σ 的配置点、<em>B</em><sub>eff</sub> 与 <em>N</em><sub>req</sub> 的折算、解码器耗时占比、显存峰值构成、以及是否启用确定性缓存。缺任何一项，数字都不可跨团队比较。论文能提供的只有两列：S 与前向次数的线性关系，以及 σ 对随机性的开关作用；其余列必须自测。</p>\n<p>一个可执行的判断规则：若解码器耗时占端到端延迟的比例超过前向部分，则压缩 S 的边际收益递减，应优先优化解码器或改用更低成本的还原路径；若显存峰值由 <em>k</em> · <em>N</em><sub>req</sub> · 激活主导，则先降 <em>B</em><sub>eff</sub> 再谈 S，因为降 S 只减时间不减峰值。这条规则把论文的机制结论翻译成了部署侧的取舍顺序，也解释了为什么材料中“不能把 DDIM 的步数收益直接换算为吞吐提升”这句话是硬约束而非保守措辞。</p>\n<p>最后落在调度表本身：步数压缩会放大单步误差，高噪声段与低噪声段的调度点选取直接影响低步数下的细节质量，这是调度实现层面的工程取舍，也是唯一一个既在论文机制内、又能被服务端直接控制的旋钮。把调度点选取与最小步数下限写进 SLO，比争论一个不可核验的加速倍数更有意义。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-49\">四十九 · 确定性采样的口径陷阱：步数收益不等于吞吐收益</h3>\n<p>把 DDIM 当作服务端加速手段时，最容易犯的错是把「步数从数百降到数十」直接读成「吞吐提升数倍」。真实口径是：单请求前向次数等于所选步数 S，延迟里只有网络前向部分随 S 线性下降，而提示编码、初始隐变量分配、VAE 解码与调度开销与 S 无关，占比在低步数区间迅速上升。设单步前向耗时 t_f、固定开销 t_0，则单请求延迟 T(S)=S·t_f+t_0，加速比上限为 (S_high·t_f+t_0)/(S_low·t_f+t_0)，当 S_low 逼近 t_0/t_f 时收益饱和。更关键的是，CFG 使有效批大小为请求数乘分支数，显存与单步激活随批线性增长，吞吐受显存折算并发而非步数单独支配——步数减少释放的是队列占用时长，不是显存容量。</p>\n<p>因此跨方案比较必须先对齐四件事：模型权重与分辨率、硬件档位与并行拓扑、batch 与并发口径（是否含 CFG 双分支）、指标定义（TTFT 与 TPOT 在扩散里对应首步与后续每步，吞吐应按「完成请求数/秒」而非「样本/秒」计）。论文材料未给出数据集规模、FID 数值与硬件档位，任何把 DDIM 步数收益换算成服务端吞吐提升的说法都不可核验。可比的只有同一权重、同一 S 调度表下的前向次数比值；不可比的是不同 σ_t 设置下的质量数字——σ_t=0 的确定性与马尔可夫对应值的随机采样，样本分布本身不同，FID 类指标的口径已变。</p>\n<table class=\"mini\"><thead><tr><th>口径项</th><th>可比条件</th><th>不可比情形</th></tr></thead><tbody><tr><td>步数收益</td><td>同权重、同调度点、仅改 S</td><td>换 σ_t 后质量曲线不可直接并列</td></tr><tr><td>吞吐</td><td>同显存折算并发、含 CFG 分支</td><td>只报样本/秒不报请求完成率</td></tr><tr><td>质量</td><td>同隐变量分布与评测集</td><td>确定性单样本对比随机多采样</td></tr></tbody></table>\n<p>失效条件集中在两处。其一，步数压到极低时单步误差被放大，高噪声段与低噪声段的调度点选取直接决定高频细节是否崩坏，需按 SLO 设最小步数下限而非一味追低；低精度量化下误差更敏感，需评估步数补偿，材料未给量化方案，不能假定 FP8/NVFP4 下步数收益不变。其二，确定性映射使同一隐变量只出一个结果，批量服务必须为每请求分配不同隐变量才能维持多样性，缓存复用与重试一致性带来的收益要以额外隐变量管理与结果比对逻辑为代价。工程判断是：把 S 当作可调服务参数，用「前向次数×批内有效样本数」估算算力占用，用固定开销占比判断加速比天花板，而不是把论文的步数压缩比直接写进容量规划。</p>\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-50\">五十 · 迁移到非扩散生成器：先看反向链是否真的存在</h3>\n<p>DDIM 的推理替换有一个硬前提：被替换的对象必须拥有一条以噪声预测网络为中心的反向链，且该链的时间步系数 α_t 与训练目标绑定。迁到别的模型时，第一个判断不是“能不能套公式”，而是“目标模型有没有这条链”。对标准扩散、视频扩散、扩散 Transformer，链存在，迁移只是调度表与系数实现；对自回归 LLM、扩散语言模型（如并行解码的 dLLM），链的形态不同——LLM 没有 α_t 的噪声日程，dLLM 的“去噪”发生在 token 空间而非连续隐空间，直接把 DDIM 的解析式搬过去会得到一个无意义的 x0 估计。工程判断是：迁移成本最低的是同一噪声日程下的连续隐空间生成器；跨到离散 token 空间时，DDIM 只提供“确定性映射 + 可复现”的思想，公式本身不可复用，需要重新推导转移系数。</p>\n<p>具体机制上，DDIM 每步的代价是<span class=\"formula\">$$x_{t-1}=\\sqrt{\\alpha_{t-1}}\\,\\hat{x}_0+\\sqrt{1-\\alpha_{t-1}-\\sigma_t^2}\\,\\epsilon_\\theta(x_t,t)+\\sigma_t\\,\\epsilon$$</span>其中 <span class=\"formula\">$$\\hat{x}_0=(x_t-\\sqrt{1-\\alpha_t}\\,\\epsilon_\\theta(x_t,t))/\\sqrt{\\alpha_t}$$</span>。迁到新模型时，α_t 序列、ε_θ 的输出语义（噪声还是速度 v）、以及 x_t 的维度都必须对齐；任何一项错位，解析出的 x0 就会偏离流形，低步数下直接表现为结构崩坏。代价体现在单步：一次前向的激活规模由隐空间分辨率决定，视频扩散的隐空间含时间维，单步激活显存远高于图像扩散，同样步数下批内并发要按帧数折算，而不是按请求数折算。</p>\n<p>例子：把一个图像扩散模型换成视频扩散模型做少步采样，若沿用图像的调度点密度，高噪声段的时间维尚未收敛，低噪声段又已过度平滑，结果是帧间闪烁而非单帧模糊——这是调度点与隐空间维度不匹配的典型症状，不是步数本身的问题。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-51\">五十一 · 迁到蒸馏与一致性模型：确定性映射是接口，不是终点</h3>\n<p>DDIM 与后续少步路线的接合点在“确定性映射”这一接口：σ_t=0 时，隐变量到样本是可逆、可复现的变换，蒸馏与一致性模型正是把这个映射从多步压成一到两步。迁移时要注意，DDIM 提供的是教师侧的采样轨迹，学生模型蒸馏需要的是这条轨迹上的 (x_t, x_{t-1}) 配对；如果教师侧改用随机采样（σ_t 取马尔可夫对应值），配对就带随机性，蒸馏目标方差变大，学生收敛更慢。工程判断：给学生模型做数据时，教师侧应固定 σ_t=0 并固定调度表，让配对可复现，否则同一隐变量每次采样出的轨迹不同，蒸馏数据无法缓存复用。</p>\n<p>代价方面，蒸馏把前向次数从 S 降到 1–4，但教师侧生成配对数据的离线成本按 S 线性增长；若 S 取数十，配对数据生成的 GPU 小时数是部署侧收益的隐性成本。规模上限在这里第一次显现：蒸馏的收益上限由教师模型在极低步数下的质量决定，DDIM 的调度点选取决定了这个上限——教师在高噪声段调度过稀，学生学到的粗结构就不稳，再蒸馏也补不回来。</p>\n<p>例子：一致性模型要求同一隐变量在不同时间步映射到同一样本，这正好复用 DDIM 的确定性性质；若把 DDIM 换成随机采样器做教师，同一隐变量在不同步的 x0 估计不一致，一致性损失的前提被破坏，训练会退化为普通蒸馏。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-52\">五十二 · 迁到量化与低精度：误差放大的方向不对称</h3>\n<p>DDIM 对数值误差敏感，且敏感度在时间轴上不对称。低步数下，高噪声段的 ε_θ 误差被 √(1−α_t) 放大后进入 x0 估计，低噪声段的误差则更多留在残差里；量化引入的激活与权重误差在这两段的表现不同。迁移到 FP8/NVFP4 推理时，判断顺序是：先确认 ε_θ 的输出动态范围是否被低精度表示覆盖，再确认 α_t 系数的累加是否在低精度下损失有效位。工程上可做的补偿是给高噪声段保留更高精度或增加该段调度点密度，而不是全局提精度——全局提精度会吃掉量化的吞吐收益。</p>\n<p>代价是显存带宽与算力：低精度把单步前向的字节数降下来，但 DDIM 的瓶颈在低步数时往往从算力转向调度与批同步，量化收益被摊薄。规模上限在于：步数越低，单步误差占总误差的比例越高，量化噪声与步数压缩的误差叠加，存在一个“再低就不划算”的拐点，这个拐点只能靠质量回归扫描定位，不能靠公式推。</p>\n<p>例子：同一模型在 FP16 下 S=20 可用，切到 FP8 后 S=20 的高频细节出现块状伪影，把 S 提到 30 才恢复；这说明量化不是免费的步数，迁移时必须把“最小步数下限”与精度档位一起标定。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-53\">五十三 · 迁到服务端批调度：可复现性是缓存的前提，也是并发的约束</h3>\n<p>确定性采样让同一隐变量与提示在任意副本上输出一致，这直接支撑重试、结果缓存与副本间比对；但批量服务要求每请求分配不同隐变量，否则批内样本完全相同，多样性归零。迁移到连续批处理框架时，批内样本必须共享同一时间步调度才能合并前向，而不同请求的 S 可能不同——工程判断是：把 S 作为请求级参数会让批内步数不一致，破坏合并；可行做法是按 S 分桶，同桶内合并，桶间独立调度。代价是桶切换带来的批利用率下降，S 取值越分散，利用率越低。</p>\n<p>CFG 的双分支前向使有效批大小为请求数乘以分支数，显存占用与单步激活随有效批线性增长；确定性模式下双分支结果可复现，缓存键要包含提示、隐变量、S、σ_t 与 CFG 强度，任一变化都使缓存失效。规模上限在于批内步数一致性与显存折算：有效批受单步激活规模约束，而单步激活又随隐空间分辨率增长，分辨率越高，可合并的请求越少，DDIM 的步数收益越难转化为吞吐收益。</p>\n<p>例子：一个服务把 S 固定为 20 并对所有请求合并，遇到需要 S=50 的高质量请求时只能单独排队，队列占用时长按 S 线性拉长；把 S 做成两档桶后，批利用率回升，但两档之间的切换点需要按到达率与 SLO 调，属于容量规划而非采样器本身的问题。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-54\">五十四 · 不适用与规模上限：三条硬边界</h3>\n<p>第一条边界是多样性需求。确定性采样下一隐变量只出一个结果，需要多样本候选的场景（如批量素材生成、多方案筛选）必须为每候选分配独立隐变量，成本按候选数线性增长；此时 DDIM 的步数收益仍在，但“一次采样多结果”的旧用法失效，迁移要改的是请求形态而非采样器。</p>\n<p>第二条边界是极低步数的细节质量。非马尔可夫框架仍依赖原模型的噪声预测精度，步数压到个位数时单步误差累积，高频细节损失明显；方差参数 σ_t 没有理论最优解，只能实验扫描。工程判断：最小步数应由 SLO 的质量下限反推，而不是由“能跑多低”决定；把 S 当可调服务参数的前提是有一条质量回归曲线，否则调低只是把失败模式推给用户。</p>\n<p>第三条边界是可核验性。材料未给出数据集规模、FID 数值与硬件档位，服务端的吞吐、显存与量化代价无法从论文核验，只能定性判断步数与前向次数的线性关系。迁移到生产时，任何“步数减半、吞吐翻倍”的换算都必须由本地基准补齐，不能引用论文结论。规模上限最终落在：步数收益是线性的，而质量下限、批利用率与精度档位共同决定这条线性收益能被兑现多少；三者任一成为瓶颈，DDIM 的迁移就只剩机制价值，没有部署价值。</p>\n\n<h3 id=\"paper-denoising-diffusion-implicit-models-2020-sec-55\">五十五 · 确定性采样的边界：从“能换调度”到“不能省前向”</h3>\n<p>迁移这套方案时，最先要判断的不是“能不能换采样器”，而是“换完之后省下的到底是什么”。DDIM 的零方差特例把转移写成 <span class=\"formula\">$$x_{t-1}=\\sqrt{\\alpha_{t-1}}\\,\\hat{x}_0+\\sqrt{1-\\alpha_{t-1}}\\,\\epsilon_\\theta(x_t,t)$$</span>，其中 <span class=\"formula\">$$\\hat{x}_0=(x_t-\\sqrt{1-\\alpha_t}\\,\\epsilon_\\theta(x_t,t))/\\sqrt{\\alpha_t}$$</span>，随机项 <span class=\"formula\">$$\\sigma_t\\epsilon$$</span> 被彻底移除。这意味着单请求的前向次数严格等于所选步数 S，不存在“跳步但补算”的余地——省的是网络前向，不是解析计算。把它迁到任何新模型上，第一件事是核对反向链是否仍以噪声预测网络为中心；若目标模型改用了 v-prediction、flow matching 的 velocity 场，或干脆是蒸馏后的少步学生模型，系数表必须按新的参数化重推，<span class=\"formula\">$$\\hat{x}_0$$</span> 的解析式也要跟着换，否则确定性映射在数值上不成立。工程上这属于调度表与系数实现的替换，权重不动，但“零重训”不等于“零推导”。</p>\n<p>失效条件集中在两处。其一是多样性：<span class=\"formula\">$$\\sigma_t=0$$</span> 时同一隐变量与提示在任意副本上输出完全一致，这既是重试、缓存与结果比对的基础，也是批量服务的硬约束——每请求必须分配不同隐变量，否则整批退化为同一张图。其二是低步数下的误差放大：调度点若只覆盖高噪声段，低噪声段的高频细节没有足够的前向去收敛，单步误差会沿链累积，表现为纹理崩坏而非整体构图失败。因此最小步数下限应由 SLO 反推，而不是把 S 当吞吐旋钮一味压低。中间值 <span class=\"formula\">$$\\sigma_t$$</span> 可折中随机性与质量，但它没有理论最优解，只能实验扫描，这本身就是一个部署期的调参成本。</p>\n<p>规模上限来自前向次数与批显存的耦合。CFG 在批内表现为双分支前向，有效批大小为请求数乘以分支数，单步激活随批线性增长；步数从数百降到数十确实线性削减延迟，但材料未给出量化与显存数据，不能把步数收益直接换算成吞吐提升。迁到 KV cache 型自回归模型或需要跨步保留中间态的架构时，这套“只保留当前 x_t 与网络激活”的假设不成立，缓存复用逻辑要重写。判断标准很直接：若目标负载的瓶颈在网络前向次数，DDIM 式确定性调度值得迁；若瓶颈在显存带宽或解码器后处理，步数压缩的收益会被摊薄，此时应优先核对调度点覆盖与最小步数下限，而不是继续追低 S。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Denoising Diffusion </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Implicit Models</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2020 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Denoising Diffusion Imp… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>未给出</td></tr><tr><td>基线</td><td>马尔可夫扩散采样（原模型的反向链）</td></tr><tr><td>主要结果</td><td>论文报告在相同预训练模型下，DDIM 用远少于原扩散的采样步数即可得到质量…</td></tr><tr><td>消融</td><td>论文对采样步数与方差参数 σ 做了对比：σ 取 0 得确定性采样，取马尔可…</td></tr><tr><td>局限</td><td>材料未给出定量指标与数据集细节，无法核验不同步数下的质量曲线；非马尔可夫框…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-denoising-diffusion-implicit-models-2020 · 共 9 个片段</p>\n";break;}}})();
